window.POEM_DB=window.POEM_DB||{};POEM_DB["song_024"]={"n":"项安世","dyn":"宋","poems":[{"t":"有感","f":"七言律诗","c":["我与昔贤生异世，昼思夜梦两微茫。","掉头堕雾入东海，被发乘风下大荒。","仙伯已寻丹灶地，武皇亦返白云乡。","惟应诗卷留天地，宝气虽埋斗有光。"]},{"t":"有感","f":"七言律诗","c":["策策秋声起树枝，遥怜塞下雁来时。","宁闻中夜荒鸡舞，肯拾他人竹马骑。","短剑旧曾交侠客，小诗犹作将偏师。","无情却是青铜镜，刚照书生两鬓丝。"]},{"t":"闻城中募兵有感 其一","f":"七言律诗","c":["调发年多籍半空，虎符招补至闽中。","庄农戎服来操戟，太守儒装学拍弓。","去日初辞乡树绿，到时愁见戍旗红。","募金莫作缠头费，留制衣袍禦北风。"]},{"t":"有感韩曾一首","f":"七言律诗","c":["道散斯文体尚浮，韩曾力与化工侔。","山瞻泰岱岩岩耸，河出昆崙混混流。","长庆从官销不得，熙宁丞相挽难留。","沧州奏疏潮州表，犹被人拈作话头。"]},{"t":"濯足万里流","f":"楚辞体","c":["将子无涉水，水深下无极。","鯈鱼舞浮阳，螭首闯阴碧。","弱去一羽沉，恶来万波激。","子兮何所求，快此蛟蜒滴。","谏议起阳城，拾遗招李渤。","望子子不来，羊裘号逋客。","踞坐山石粗，晞发朔风急。","乱流两白足，何日踔疏逸。","子兮宁不悲，饥氓徯唐稷。","岂其洛之涯，而可温与石。"]},{"t":"七月二十日被檄考试出门 其一","f":"七言绝句","c":["阿婆少也不如人，更说秋来白发新。","欲按新声忘旧谱，画鸾歌扇久生尘。"]},{"t":"二十一弟寿二首 其二","f":"七言绝句","c":["叹兄龌龊身全老，喜弟生狞脸正童。","色要如童长不改，学须似老始多功。"]},{"t":"二十一弟寿二首 其一","f":"七言绝句","c":["肇开元圣千年学，曾是吾家七岁童。","门户只今须自力，诗书排日看新功。"]},{"t":"二十九日过小将军大将军岭","f":"七言绝句","c":["复岭参差意出群，行人遥指两将军。","黥彭只么空山老，不向中原早策勋。"]},{"t":"二十二日山行","f":"五言绝句","c":["秋日更山行，朝朝入画屏。","雨看如水墨，晴唤似丹青。"]},{"t":"二十三日阻雨鸭陂驿因写道中诗寄罗郢州","f":"七言绝句","c":["横吹逆洒断人行，破驿孤眠又一程。","写得吴笺寄长寿，无情风雨却多情。"]},{"t":"二十五日岳市路口居人皆鬻栉具及风药","f":"七言绝句","c":["家家药榜丸朱墨，处处丝绳罥比梳。","我有沉疴并宿垢，亦思从此日祛除。"]},{"t":"二十六日慈竹二首 其二","f":"五言绝句","c":["郁郁带春阴，依依绕故林。","何人化南裔，草木有仁心。"]},{"t":"二十六日慈竹二首 其一","f":"五言绝句","c":["慈竹村村种，鞭行不出林。","吾亲在何许，回首白云深。"]},{"t":"二十四日看山","f":"七言绝句","c":["日日凭舆看远山，不知行处是峰峦。","他山亦有痴人看，却向侬家行处看。"]},{"t":"入江西界","f":"七言绝句","c":["行过中村五里头，湖南地尽到袁州。","荆南更在湖南外，一片白云天际浮。"]},{"t":"入普州","f":"七言绝句","c":["过尽昌州无数山，山开地辟见平田。","田中有麦元无米，比自昌州却可怜。"]},{"t":"入湖北界","f":"七言绝句","c":["丹楹白扁照人开，湖北封疆直面来。","入得界头欢喜倒，恰如身已到荆台。"]},{"t":"十月旦日上冢过渚宫避雨二首 其二","f":"七言绝句","c":["一机寒水小吴绫，数幅荒林老画屏。","却恐秋光太憔悴，照天宫锦拒霜明。"]},{"t":"十月旦日上冢过渚宫避雨二首 其一","f":"七言绝句","c":["萦纡白道转城腰，寂寞垂杨倚画桡。","独自练光亭上坐，净慈烟雨看长桥。"]},{"t":"又赠刘正将","f":"七言绝句","c":["义山仙去飞卿死，今代刘郎以字行。","吟到江都燕台曲，一生深处许谁明。"]},{"t":"三十七岁初见白发诗","f":"七言绝句","c":["亲朋相见忽相惊，绿发朝来白两茎。","若比商州王副使，预先搀得一年生。"]},{"t":"上鄂州黄鹤矶","f":"七言绝句","c":["黄鹤矶头水似油，赵陀埽上石如钩。","舟人上得休誇客，曾过人间百仞流。"]},{"t":"大旱小雨 其一","f":"七言绝句","c":["白水连天九泽浑，平田五月献龟纹。","北人未识黄梅雨，千里争占赤土云。"]},{"t":"大旱小雨 其二","f":"七言绝句","c":["稍觉丝丝来万弩，如闻隐隐动千军。","夜窗一霎聊堪睡，未救田家卒岁勤。"]},{"t":"小雨怀张升之","f":"七言绝句","c":["夜窗疏雨不堪听，独坐寒斋万感生。","今夜故人江上宿，如何禁得打篷声。"]},{"t":"中秋无月","f":"七言绝句","c":["青天碧海路悠悠，兔老蟾饥亦倦游。","锁定玉楼云不卷，两街灯火作中秋。"]},{"t":"中秋阻风二首 其二","f":"七言绝句","c":["四无边岸贴天流，八极光中一钓舟。","不是南风解留客，世间无此好中秋。"]},{"t":"中秋阻风二首 其一","f":"七言绝句","c":["二月当官八月来，先生官意本衰颓。","乾坤老大知心久，日日南风滞去桅。"]},{"t":"五月八日离金陵","f":"五言绝句","c":["舟移石头岸，路转马鞍矶。","惟有长干塔，相看未忍违。"]},{"t":"元夕二首 其一","f":"七言绝句","c":["腊雪初消御路乾，暖风吹面不成寒。","月华满地春如酒，不是烧灯也合看。"]},{"t":"凤凰台","f":"七言绝句","c":["凤凰何处不归来，衰草斜阳只废台。","欲唤谪仙歌一曲，长安今日更堪哀。"]},{"t":"天申节锡宴戴花","f":"七言绝句","c":["泥金撚铁缀花枝，浅白深红映酒卮。","回首琼林真一梦，插花还似去年时。"]},{"t":"天阴欲雪","f":"七言绝句","c":["仰天再拜乞冬晴，十县租人要入城。","些子中间私意处，此身方在客中行。"]},{"t":"巴河","f":"七言绝句","c":["纷纷剑客走淮濆，破虏红袍海内闻。","行到巴河打叉处，居人犹识旧将军。"]},{"t":"忆田间事","f":"五言绝句","c":["小盖行障日，枯筇立倚风。","入田催种稻，行圃看浇葱。"]},{"t":"方太君生朝四首 其四","f":"七言绝句","c":["天边历草记年华，一日东风一荚花。","春到平分争一荚，庭萱吹出碧云芽。"]},{"t":"方太君生朝四首 其三","f":"七言绝句","c":["不须蟾桂十分圆，自有春花万种妍。","岁岁年年长寿酒，海棠开后牡丹前。"]},{"t":"方太君生朝四首 其二","f":"七言绝句","c":["月姊飞来二月天，万花香里十分圆。","谁教婺女星知道，一夜搀先照画筵。"]},{"t":"方太君生朝四首 其一","f":"七言绝句","c":["夹钟琯里听春声，天上箜篌次第鸣。","数到一弦弦足处，孟家机畔庆长生。"]},{"t":"水仙二首 其二","f":"七言绝句","c":["小窗寒夜见冰花，骨冷魂清梦不邪。","薝卜花头萱草树，只应常在野人家。"]},{"t":"水仙二首 其一","f":"七言绝句","c":["川后冰幢下碧湍，玉妃前导驾青鸾。","素罗襦下青罗带，碧玉簪头白玉丹。"]},{"t":"水宿","f":"五言绝句","c":["水纳乾坤净，窗通左右凉。","船门如引索，直面看波光。"]},{"t":"长亭解","f":"七言绝句","c":["行人处处论亭邮，总为长亭怕永州。","不道长亭更长去，也应行到日西休。"]},{"t":"东斋","f":"七言绝句","c":["桃花不解言前事，菊蕊还须记旧人。","惟有轩前旧移竹，向人憔悴似相嗔。"]},{"t":"主台州崇道观","f":"七言绝句","c":["蓬莱别后六经春，新赐丹邱作羽人。","恰似昔人东望处，蓬莱径隔几由旬。"]},{"t":"兰溪道中二首 其二","f":"七言绝句","c":["一夜清霜逗晓晴，桑林脱叶似滩声。","云边恰有惊鸿过，直作滩头细橹鸣。"]},{"t":"兰溪道中二首 其一","f":"七言绝句","c":["征人颊热共占霜，忽报冬温是雨祥。","正向愁边闻吉语，三霜两假是寻常。"]},{"t":"出江陵北门便有诗思","f":"七言绝句","c":["反闭柴门谢绝诗，二年强饭慰肝脾。","朝来威远门前路，已被渠侬圣得知。"]},{"t":"四月五日解维成都连日行浅滩中或迟或速如在东中游湖甚以为乐初九日过龙爪滩两江合流江始深舟人至此歌呼鸣橹作发船离岸之声余始怆然觉身是行客颇有离索之念","f":"七言绝句","c":["青林浅濑密萦洄，唤作兰亭载酒来。","忽听江深发鸣橹，始知身是罢官回。"]},{"t":"失题","f":"七言绝句","c":["梦回似觉前身误，蜕罢便寻芳草吟。","吟到夕阳人不恨，满怀风露本无心。"]},{"t":"玄蝶","f":"七言绝句","c":["腰肢可爱红娘子，面目无情黑老婆。","世上但知怜少艾，双双飞舞奈渠何。"]},{"t":"用韵寄四川总领陈郎中 其二","f":"七言绝句","c":["笔稀秋老墨花春，散作烟云段段新。","闻有清诗心便渴，径烦珍字写西宾。"]},{"t":"用韵寄四川总领陈郎中 其一","f":"七言绝句","c":["天上归来睡九春，一封黄牒拜除新。","赤城洞府今为主，抚掌群仙总是宾。"]},{"t":"田间观雨忆叶正则旧话","f":"七言绝句","c":["风中晚稻离离长，雨后高田聒聒流。","此乐世间谁共赏，淮西使者正防秋。"]},{"t":"田间草花","f":"七言绝句","c":["十里五里望不断，白花红花俱可怜。","无姓无名天下乐，自开自落卉中仙。"]},{"t":"田家有感","f":"七言绝句","c":["秋田犁罢老农閒，岁暮无营只闭关。","愧我西来复东去，新年赢得鬓毛斑。"]},{"t":"石滑澾岭 其二","f":"七言绝句","c":["滑澾岭上十年前，黄泥白石故依然。","旧时茅舍无寻处，一我能消几十年。"]},{"t":"石滑澾岭 其一","f":"七言绝句","c":["脚穿行到石滑澾，耳鸣听得提葫芦。","乱山无数日欲落，一声美酒宽征夫。"]},{"t":"立春日离家闻有召试之命","f":"七言绝句","c":["东行就日北看云，君宠亲恩两系心。","毕竟刍荛何所补，不如留著在山林。"]},{"t":"立夏日南风大作二首 其二","f":"七言绝句","c":["满城杨柳绿依依，背著春风自在飞。","却是杨花有才思，一时收拾伴春归。"]},{"t":"立夏日南风大作二首 其一","f":"七言绝句","c":["堤边树子最无情，恰则春归第一程。","舞向南风浑不住，叶间羞损旧啼莺。"]},{"t":"记梦","f":"五言绝句","c":["共客谈风雅，花边或水边。","胸中无一事，梦里亦欣然。"]},{"t":"安园送春三首 其三","f":"七言绝句","c":["春风从此不须归，伴我逍遥更莫疑。","閒事胸中无一点，相看日日是春时。"]},{"t":"安园送春三首 其二","f":"七言绝句","c":["未信飞花取次空，绕园千步觅春风。","元来都在榴花上，百摺芳心一并红。"]},{"t":"安园送春三首 其一","f":"七言绝句","c":["春归重到是何时，满劝教渠醉似泥。","长短亭前芳草满，醉中归去路应迷。"]},{"t":"有感","f":"五言绝句","c":["船头一摇桨，船尾万波随。","闻道山中乐，无人尽日维。"]},{"t":"次韵叶教授小院室中瓶梅二首 其二","f":"七言绝句","c":["暖冰融雪浸疏梅，养住春风细细开。","相赏阿咸清到骨，风流元自竹林来。"]},{"t":"次韵叶教授小院室中瓶梅二首 其一","f":"七言绝句","c":["半瓻冰水一簪梅，的皪寒花数点开。","疏影已从灯畔见，暗香时向梦中来。"]},{"t":"次韵孙佥判试院中秋咏月三绝 其二","f":"七言绝句","c":["挥毫可但佐摛文，照破平生种种尘。","一点清明如古镜，八方圆转似车轮。"]},{"t":"次韵孙佥判试院中秋咏月三绝 其一","f":"七言绝句","c":["鸾驾乘风上玉清，青冥风露湿琼英。","我时独笑无人解，四海诸公共此明。"]},{"t":"次韵孙佥判试院中秋咏月三绝 其三","f":"七言绝句","c":["此夜清光万古同，自开场屋几番逢。","如今压倒诗人后，不许狂僧打夜钟。"]},{"t":"次韵李校书雨中至四圣观三绝句 其二","f":"五言绝句","c":["花片洒行廊，苔痕上赭墙。","阜陵游幸处，花草亦悲凉。"]},{"t":"次韵李校书雨中至四圣观三绝句 其一","f":"五言绝句","c":["今日真仙宅，当年处士家。","江梅疏影尽，无数海棠花。"]},{"t":"次韵李校书雨中至四圣观三绝句 其三","f":"五言绝句","c":["积雨全迷路，皇天不做春。","提壶休劝客，城外有饥人。"]},{"t":"次韵苏主管青溪十绝句 其四","f":"七言绝句","c":["雨馀溪水十分盈，更著秋潮数寸生。","西浸夕阳东浸月，并于池面作鲜明。"]},{"t":"次韵苏主管青溪十绝句 其一","f":"七言绝句","c":["与君相别若耶溪，十载湘航与蜀梯。","恰到六朝行乐处，台城东畔冶亭西。"]},{"t":"次韵苏主管青溪十绝句 其六","f":"七言绝句","c":["多谢西风护绿漪，不教一点动琉璃。","并留杨柳春时叶，总向琉璃四面垂。"]},{"t":"次韵苏主管青溪十绝句 其二","f":"七言绝句","c":["不分诗颠著病魔，一杯姜酒汗滂沱。","须臾下笔风雷吼，写尽清溪曲曲波。"]},{"t":"次韵苏主管青溪十绝句 其三","f":"七言绝句","c":["日西何事客归迟，等看娟娟一寸眉。","却是嫦娥太誇客，和宫推出桂花枝。"]},{"t":"次韵苏主管青溪十绝句 其八","f":"七言绝句","c":["墙头红旆醉僛僛，大将防江出六奇。","我自中原行铁马，他时此物不劳施。"]},{"t":"次韵苏主管青溪十绝句 其五","f":"七言绝句","c":["风前月放玉杯圆，雨后云拖翠缕纤。","月要钟山全体现，云师只肯露微尖。"]},{"t":"次韵苏主管青溪十绝句 其九","f":"七言绝句","c":["不须北阜与西凉，城里溪亭剩得狂。","风过静观波治乱，云閒閒看月兴亡。"]},{"t":"次韵苏主管青溪十绝句 其十","f":"七言绝句","c":["老翁何处已飞仙，想跨寒驴挟短鞭。","来往段家池上路，只今枯柳尚鸣蝉。"]},{"t":"次韵苏主管青溪十绝句 其七","f":"七言绝句","c":["清溪元有几家湾，留得如今一曲残。","六代旧人无处问，只馀淮水与钟山。"]},{"t":"次韵苏教授饭郑教授五首 其五","f":"七言绝句","c":["三生杜牧垂纶手，渠自长安障日头。","我意从来端易败，分司御史莫来休。"]},{"t":"次韵苏教授饭郑教授五首 其四","f":"七言绝句","c":["叹息吾家老郑君，三年孤鹤困鸡群。","天教此地苏司业，与对当时郑广文。"]},{"t":"次韵苏教授饭郑教授五首 其三","f":"七言绝句","c":["采蘋堪赋有斋诗，稚子谈经已大奇。","翁但绿阴啼鸟下，敷床眠到日西时。"]},{"t":"次韵苏教授饭郑教授五首 其二","f":"七言绝句","c":["琼枝璧月夜争新，玉粒云抄岁有陈。","列屋万钟祇此是，更须骑马傍何人。"]},{"t":"次韵苏教授饭郑教授五首 其一","f":"七言绝句","c":["卧龙山下鹿门居，消得幽人一草庐。","更有胜如诸葛处，稻花香里看芙蕖。"]},{"t":"次韵连通州祷雨弥勒像二绝句 其一","f":"七言绝句","c":["欲呼弥勒下天宫，云叶森森意已浓。","尘世为霖消底物，葛陂龙是向来筇。"]},{"t":"次韵连通州祷雨弥勒像二绝句 其二","f":"七言绝句","c":["田父占云控血诚，治中得句写江清。","若为古堰千龟裂，得似词源万斛倾。"]},{"t":"次韵和黄江陵重午二绝 其二","f":"七言绝句","c":["老便蜜粽加餐易，病却蒲根细嚼难。","系腕只馀心似结，沐芳谁与臭如兰。"]},{"t":"次韵和黄江陵重午二绝 其一","f":"七言绝句","c":["门前帖子虫书小，壁上仙人虎脊高。","欲起沉疴无旧艾，枕边霜鬓日萧骚。"]},{"t":"次韵罗郢州送别","f":"七言绝句","c":["江上相留不肯留，渡江沿岸却回头。","汉江东去人西去，不见高城始是愁。"]},{"t":"次韵谢张安抚以诗送梅实 其二","f":"七言绝句","c":["水边篱落数花疏，马上行人且勿驱。","一堕冰盘永相望，故人怜我误为儒。"]},{"t":"次韵谢张安抚以诗送梅实 其四","f":"七言绝句","c":["梦随清浅看扶疏，军将敲门报疾驱。","此解可辞儿女笑，使君风味似寒儒。"]},{"t":"次韵谢张安抚以诗送梅实 其一","f":"七言绝句","c":["此物从来作计疏，洛阳樱笋正驰驱。","绝知不可时人口，只有微酸惬腐儒。"]},{"t":"次韵谢尚书赠曾术人","f":"七言绝句","c":["淡墨当中印八神，众星环写象秋旻。","逢人只说忠和孝，莫道鸣珂与曳绅。"]},{"t":"次韵潘都干元夕","f":"七言绝句","c":["春草萋萋六代陵，元宵风景属残僧。","街头年少浑无事，共点油钱放塔灯。"]},{"t":"次韵颜运使伏龙山诸葛祠堂二首 其二","f":"五言绝句","c":["大义炯如新，千年报国身。","宁从东海死，不作帝秦人。"]},{"t":"次韵颜运使伏龙山诸葛祠堂二首 其一","f":"五言绝句","c":["羽扇白纶巾，堂堂六尺身。","我评秦汉下，宇宙只斯人。"]},{"t":"次韵衡山徐监酒同考府学试八首 其七","f":"七言绝句","c":["夜久看书眼倍明，春来觅句思偏精。","不嗔科举遗佳士，更把时文教后生。"]},{"t":"次韵衡山徐监酒同考府学试八首 其六","f":"七言绝句","c":["南州门户到云来，犹有诗情出九垓。","怜我风帘钻故纸，借君月露洗黄埃。"]},{"t":"次韵衡山徐监酒同考府学试八首 其五","f":"七言绝句","c":["烛灺灯枯夜漏残，眼眵腰折吻声乾。","上床一觉江南梦，放艇高歌七里滩。"]},{"t":"次韵衡山徐监酒同考府学试八首 其四","f":"七言绝句","c":["欲浓还淡云容碎，似见如藏日影微。","赚得鸠声长又短，不知雨意是耶非。"]},{"t":"次韵衡山徐监酒同考府学试八首 其三","f":"七言绝句","c":["世间无事可关心，只有丰年愿最深。","春旱恼人头欲白，朝来一雨万黄金。"]},{"t":"次韵衡山徐监酒同考府学试八首 其一","f":"七言绝句","c":["诗里无悰久自知，意来聊复寄于斯。","要知风节高多少，万事如今总似诗。"]},{"t":"次韵黔阳王令论诗五绝句 其三","f":"七言绝句","c":["骊珠一百二十六，落纸轻圆字字同。","怪得春来全少雨，烟云都在锦囊中。"]},{"t":"次韵黔阳王令论诗五绝句 其一","f":"七言绝句","c":["洞庭五百里巨浸，衡岳七十二高峰。","不是公家椽样笔，个中施手若为容。"]},{"t":"次韵黔阳王令论诗五绝句 其五","f":"七言绝句","c":["我亦童年学露蛩，老来留眼送归鸿。","自从谢绝曹刘后，浩荡春光满太空。"]},{"t":"次韵黔阳王令论诗五绝句 其二","f":"七言绝句","c":["旧日辋川图上翁，而今孙子尚家风。","如何寂寞黔阳去，五两青纶一亩宫。"]},{"t":"次韵黔阳王令论诗五绝句 其四","f":"七言绝句","c":["见说吟哦三十载，从来此事一生功。","劝君莫用雕镌得，只恐今人晚更穷。"]},{"t":"江陵赠蒲术人","f":"七言绝句","c":["未赴成都先梦到，才逢蜀客便心亲。","江陵一见蒲居士，似向严家访阿遵。"]},{"t":"竹枝歌","f":"五言绝句","c":["山女带山花，狂夫未著家。","蛮歌君莫笑，曾入汉琵琶。"]},{"t":"红梅","f":"七言绝句","c":["瘦影从来雪不如，宿酲谁见绮霞舒。","道山堂下春风面，还向天涯伴校书。"]},{"t":"自子陵市寻路入游上泉三首 其三","f":"七言绝句","c":["君看酒碗涴蒙泉，玉气珠光夜索然。","可使黄尘车马客，更将此地世人传。"]},{"t":"自子陵市寻路入游上泉三首 其二","f":"七言绝句","c":["千年玉水閟深林，十里重冈隔世尘。","犹恨子陵饶舌在，却当户口告行人。"]},{"t":"自子陵市寻路入游上泉三首 其一","f":"七言绝句","c":["去年雨宿严陵市，咫尺风烟隔上泉。","今日山神方信我，不将尘土到渠边。"]},{"t":"自武义入松阳道中三首 其三","f":"七言绝句","c":["四十里栏萦一线，上侵云物下惊湍。","我行竹客源头路，蜀道青天不作难。"]},{"t":"自武义入松阳道中三首 其二","f":"七言绝句","c":["黄雾漫天作晓霜，征人相顾失颜行。","虽然未快还乡眼，脚底沙泥已是乡。"]},{"t":"自武义入松阳道中三首 其一","f":"七言绝句","c":["家家籼米与香红，客子餐腴复醉醲。","但使普天无横吏，人间何处不春风。"]},{"t":"自赞","f":"七言绝句","c":["将军下笔枉施功，羽箭贤冠事不同。","桐柏宫中狂道士，枚回洲上病渔翁。"]},{"t":"行香退过南湖主人未起","f":"七言绝句","c":["梦里敲门报五更，雨中行轿到天明。","若为得似张公子，卧听穿林打叶声。"]},{"t":"观穫","f":"五言绝句","c":["晚艇村村载，秋原处处收。","年来尤爱此，一熟缓千忧。"]},{"t":"观潮","f":"五言绝句","c":["张王偏宜月，雄豪更得秋。","岸头浑破胆，浪里有行舟。"]},{"t":"过丰城三十里始见田庐坐落","f":"七言绝句","c":["石坑东畔好田庐，更著青林映带渠。","新喻丰城三百里，中间萧索独何如。"]},{"t":"过峡州宿青草滩","f":"七言绝句","c":["烟里鸣桡去夕阳，不堪风急滞归航。","无端更著三更月，一夜孤篷一寸霜。"]},{"t":"过淞江忆郑虞任","f":"七言绝句","c":["独上吴淞第四桥，忆随郑老驻兰桡。","白头髣髴平生处，一盏寒泉赋大招。"]},{"t":"过滑澾岭","f":"七言绝句","c":["连山赤埴号胶泥，想见林深叫竹鸡。","一路新晴天借我，稳扶篮笋上山蹊。"]},{"t":"初三日解维","f":"七言绝句","c":["隐隐金钲解岸维，昏昏红日下田陂。","朦胧雾里廉纤雨，妆点行人去国诗。"]},{"t":"初春二首 其二","f":"七言绝句","c":["不寒不暖风色好，似醉似眠春意深。","嫩绿深红无一点，柳情花思自盈襟。"]},{"t":"初春二首 其一","f":"七言绝句","c":["时阔江空无片云，草枯木脱最愁人。","东风小作撩人意，已觉人间无奈春。"]},{"t":"县廨海棠盛开二绝句 其二","f":"七言绝句","c":["美人宿酒未全醒，困倚妆台睡不成。","一半醉颜无处画，似红如白最多情。"]},{"t":"县廨海棠盛开二绝句 其一","f":"七言绝句","c":["梅蕊才开杏又红，今年春事太匆匆。","堂前燕子归来到，双海棠花已满丛。"]},{"t":"听雨","f":"五言绝句","c":["幸自蓬窗好，侬家企脚眠。","雨声无赖得，相唤著愁边。"]},{"t":"寿母生朝四首 其四","f":"七言绝句","c":["儿孙遥指菊花辰，自讼庵中庆诞人。","也向此旬同此日，八千秋对八千春。"]},{"t":"寿母生朝四首 其三","f":"七言绝句","c":["良辰好景占年年，画烛浓香醉玉船。","天上月圆三夜后，人间春到万花边。"]},{"t":"寿母生朝四首 其二","f":"七言绝句","c":["荪襦兰佩拥萱阶，绿发朱颜照酒杯。","九十九洲春色里，老人星动寿筵开。"]},{"t":"寿母生朝四首 其一","f":"七言绝句","c":["堂成初见画檐新，碧瓦翚飞上綵云。","三尺宝台蒙锦帕，白狻猊顶翠氤氲。"]},{"t":"李中主书堂","f":"五言绝句","c":["楞伽有公择，娣弟如班宗。","宜州黄宅相，馀韵更舂容。"]},{"t":"步上黄罴岭","f":"七言绝句","c":["牛头鹤弄漫虚传，未抵黄罴路刺天。","曳杖徐行吾自乐，世间何地不平田。"]},{"t":"沈医送苔梅自云恨不能诗","f":"七言绝句","c":["但能为我送苔梅，何必新诗手自裁。","若使能诗有奇句，无因送与冷官来。"]},{"t":"纸阁 其一","f":"七言绝句","c":["也知无鬼瞰高明，纸阁中间万事轻。","不愿人呼贵公子，只图身作富书生。"]},{"t":"纸阁 其二","f":"七言绝句","c":["薄似秋云瑩似冰，清于寒士懒于僧。","凭谁更得移蟾法，剪取光明不用灯。"]},{"t":"还刘叔骥庐山诗卷 其一","f":"七言绝句","c":["刘家子骥我乡人，洞口桃花独问津。","岁时他乡逢叔士，杏林花发小阳春。"]},{"t":"还刘叔骥庐山诗卷 其二","f":"七言绝句","c":["浔阳江上督邮谁，能使陶公去不疑。","今代庐山非昔日，督邮能酒更能诗。"]},{"t":"阻风泊江州对岸","f":"七言绝句","c":["城下看山不见山，东风吹我过前滩。","横陈庐阜沧波上，十二云鬟得细看。"]},{"t":"阻风茅山港 其一","f":"七言绝句","c":["日日南风费挽牵，江神知我意悠然。","小舟随水随风住，不羡千帆上水船。"]},{"t":"阻风茅山港 其二","f":"七言绝句","c":["我非汲汲驰名者，何事区区逆浪间。","三釜及亲须为米，可辞为客下茅山。"]},{"t":"鸡唱歌","f":"五言绝句","c":["莫歌鸡唱晓，老泪不禁弹。","昔为祖士雅，今作杜齐安。"]},{"t":"卧病","f":"七言绝句","c":["廉纤小雨湿相欺，病客无悰昼掩扉。","自转巫屏遮午枕，一窗寒梦绕亲闱。"]},{"t":"和赵主簿韵赋桃花","f":"七言绝句","c":["曷日鲜晴后土乾，川原远近踏春寒。","诗人不问花开落，为雨为霞总爱看。"]},{"t":"和赵司户寻梅桐原庵 其二","f":"七言绝句","c":["桐原花下不容车，茅压疏檐竹绕闾。","可惯传呼青影里，人声浩浩屋渠渠。"]},{"t":"和赵司户寻梅桐原庵 其一","f":"七言绝句","c":["王孙宝马七香车，不似吟鞭跨蹇驴。","少待绿阴青子下，与君扶杖转鸣渠。"]},{"t":"夜泊闻榔","f":"七言绝句","c":["昨夜天聪门外泊，不闻朝鼓只闻榔。","三年一觉青云梦，始觉人间味许长。"]},{"t":"忠州","f":"七言绝句","c":["耕凿林庐满四山，人家境象极宽閒。","不妨五马云根住，小市孤城自掩关。"]},{"t":"松阳南岩夜归","f":"七言绝句","c":["走下南岩踏黑归，苍林拥径白光微。","马湖桥上消摇甚，飞度前村露满衣。"]},{"t":"武陵江上渔舟","f":"七言绝句","c":["家居堤下土平檐，人在江中尺许船。","正尔平生事方足，有人狂梦欲登仙。"]},{"t":"炙背","f":"七言绝句","c":["偻坐前檐曝午曦，一襟和暖似春时。","无因得共田夫比，直献君王更不疑。"]},{"t":"钓台 其一","f":"七言绝句","c":["数仞山头一小亭，只消此地过平生。","崎岖狭世才伸脚，已被刘郎卖作名。"]},{"t":"钓台 其二","f":"七言绝句","c":["君房足下竟成谀，只是韩歆已破除。","岂有江湖钓竿手，为君台阁奉文书。"]},{"t":"雨中二绝句 其二","f":"五言绝句","c":["雨过山色青，风来水花白。","不是风雨来，何因见颜色。"]},{"t":"雨中二绝句 其一","f":"五言绝句","c":["急雨暗洲渚，颠风吹客船。","不知何世画，水墨水江天。"]},{"t":"雨中早行","f":"七言绝句","c":["春烟漠漠雨霏霏，山崦人家未启扉。","刚把平生青箬笠，江南道上著征衣。"]},{"t":"临安道中见壁间书字云由左行者为四川驿路","f":"七言绝句","c":["只道成都路八千，谁知从此便西川。","行人一见成深省，大道多歧稳著鞭。"]},{"t":"亭午热甚过石子涧","f":"七言绝句","c":["一掬儿童数树凉，两三桅子野花香。","荒山赤日相逢处，便是天台见石梁。"]},{"t":"南岳路口怀胡氏兄弟 其一","f":"七言绝句","c":["奕奕神山照远天，美人家在此山前。","待侬了却公家事，来借书堂十日眠。"]},{"t":"南岳路口怀胡氏兄弟 其二","f":"七言绝句","c":["虎逝龙亡不记年，旧巢双凤故依然。","灵岩草木皆堪敬，莫作寻常到岳前。"]},{"t":"将往襄阳一日大雨","f":"七言绝句","c":["谁报江神我欲西，怕传新句落檀溪。","江头一雨泥三尺，车没双轮马没蹄。"]},{"t":"峡内三绝句 其三","f":"七言绝句","c":["千崖无树作炊烟，峡内为生也可怜。","探水得柴如宝藏，卖茆成俗满村船。"]},{"t":"峡内三绝句 其二","f":"七言绝句","c":["峡内居人种石田，种成卜瓠待江船。","船头老妪悲声甚，只博茶盐不博钱。"]},{"t":"峡内三绝句 其一","f":"七言绝句","c":["峡内为生绝可怜，那知世上有平川。","生身未识三冬雪，仰面惟看一席天。"]},{"t":"思归二绝句 其一","f":"五言绝句","c":["永日消金鸭，暄风汎宝鸾。","自从归意动，无复梦魂安。"]},{"t":"思归二绝句 其二","f":"五言绝句","c":["艾叶翻翻白，榴花叠叠红。","年华惊客枕，心事逐邮筒。"]},{"t":"春日途中五首 其五","f":"七言绝句","c":["微风急雪点微茫，渔浦江边上客航。","逆水趁潮如顺水，他乡送客似离乡。"]},{"t":"春日途中五首 其四","f":"七言绝句","c":["湖海今年最倦游，春来新上浙西舟。","天寒岁暮钱清路，又踏严州向婺州。"]},{"t":"春日途中五首 其三","f":"七言绝句","c":["破艇冲风去似疑，短篷经雨漏如筛。","无端更著连宵雨，大似波神得厮欺。"]},{"t":"春日途中五首 其二","f":"七言绝句","c":["一派清江两岸平，湿云将雨暗柴荆。","十年一觉荆州梦，通济江头沌里行。"]},{"t":"春日途中五首 其一","f":"七言绝句","c":["未说离家日日晴，离家三日雨如倾。","津头小吏询名氏，但道当年段墨卿。"]},{"t":"春色三首 其三 芳草","f":"七言绝句","c":["堕粉瓢红迹已陈，却将春色付何人。","东君老去都平施，绿幕连天一样新。"]},{"t":"春色三首 其二 垂杨","f":"七言绝句","c":["春风十九归桃李，白白红红得最多。","未抵垂杨春最惜，娇娇袅袅奈渠何。"]},{"t":"春色三首 其一 桃李","f":"七言绝句","c":["花因实盛村村有，树为花繁处处明。","浩荡九州春色里，输他桃李最多情。"]},{"t":"春阴二首 其二","f":"七言绝句","c":["烟花淡淡雨声息，云脚疏疏日影红。","桃花作雨梨花雪，春在绿杨芳草中。"]},{"t":"春阴二首 其一","f":"七言绝句","c":["好风疏雨瀹红尘，收拾残花作翠阴。","春色不随桃李去，一川浓绿正深深。"]},{"t":"春晴步出东城","f":"七言绝句","c":["山北山南草渐青，去年双鬓只星星。","春风不管游人老，又到江头白下亭。"]},{"t":"秋怀 其二","f":"七言绝句","c":["秋水迢迢诗思清，秋阳杲杲道心明。","谁人得似秋光巧，画出山斋杖屦行。"]},{"t":"秋怀 其一","f":"七言绝句","c":["有营何日得无悲，无欲无时不自宜。","竹影一窗泉一曲，山斋非是爱吟诗。"]},{"t":"荆门十二背诗","f":"七言绝句","c":["瞿塘关里异乾坤，石狭山深日气昏。","行过西陵天亦晚，浪平风暖下荆门。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其二","f":"七言绝句","c":["二歌渔父寿杯宽，荆江亭下到临安。","更将海水都斟却，浅得蓬莱始好看。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其六","f":"七言绝句","c":["六歌渔父寿诗声，一声声带竹枝情。","大枝千岁不改色，小枝孙子满林生。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其七","f":"七言绝句","c":["七歌渔父寿香堆，花雾深深拨不开。","水边借得春风送，荷花吹上戟门来。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其四","f":"七言绝句","c":["四曲渔人寿烛明，明在水云连处生。","倚天若木朝朝艳，照海金波夜夜清。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其一","f":"七言绝句","c":["第一歌头缓缓催，且看渔父寿图来。","天明转向牙旗外，六千里地绣屏开。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其三","f":"七言绝句","c":["三曲渔人献寿茶，新翻衢样织茶花。","白雨纷纷下江海，翠浪滚滚开龙蛇。"]},{"t":"荆江渔父竹枝词九首和夔帅□侍郎韵为荆帅范侍郎寿 其九","f":"七言绝句","c":["九歌渔父好思量，愿得寿星朝帝乡。","寿十二庙寸关尺，演亿万年元蔀章。"]},{"t":"送潘都干往临安","f":"七言绝句","c":["西子湖边桃叶青，潘郎归骑拂春星。","金陵风景凭谁看，留得闲人住冶亭。"]},{"t":"送襄阳冯主簿 其三","f":"七言绝句","c":["不随黄绶去仇栖，归著亲前五色衣。","安得紫皇知此意，唤教霜凤带雏飞。"]},{"t":"送襄阳冯主簿 其二","f":"七言绝句","c":["老子当年起垄间，岂知零落向华颠。","秋风唤起神洲梦，犹忆平生戴与田。"]},{"t":"送襄阳冯主簿 其一","f":"七言绝句","c":["书来雍府不相忘，中有清诗小作行。","一似岘南车上读，眼中行色有辉光。"]},{"t":"郢州道中见刺玫瑰花","f":"七言绝句","c":["酴醾雨后飘春雪，芍药风前散晚霞。","一路繁香伴行客，只应多谢刺玫花。"]},{"t":"重九以枣糕饷孙司户","f":"七言绝句","c":["满城风雨近重阳，应为征廛堕渺茫。","要看诗来压奇字，试拈公案示孙郎。"]},{"t":"重午饷菜楚俗也邓抚干以诗来谢次韵答之三首 其三","f":"七言绝句","c":["蜀客登来屈子城，九歌重见笔纵横。","不妨秋露浇春菜，只可从渠学独清。"]},{"t":"重过习池","f":"七言绝句","c":["征鞍重过习家池，桥下泉声又索诗。","待洗一杯春酒涴，为君吐出碧云词。"]},{"t":"重阳前一日大风雨","f":"七言绝句","c":["天公著意做重阳，风伯驱除特地忙。","扫尽残花与红叶，放教篱菊占秋光。"]},{"t":"除夕谕铃下两绝句 其一","f":"七言绝句","c":["江边梅柳自知新，病里形容只向陈。","春色不干枯木事，明朝贺岁莫通宾。"]},{"t":"除夕谕铃下两绝句 其二","f":"七言绝句","c":["莫将新岁便为新，綵仗春幡不动陈。","未转东风犹是腊，明朝贺岁莫通宾。"]},{"t":"顺风过湖二首 其二","f":"七言绝句","c":["维舟六日傍明山，待得风来始破颜。","一抹平湖三十里，听渠微横未须关。"]},{"t":"顺风过湖二首 其一","f":"七言绝句","c":["帆影如酲左右倾，水声似战聒天鸣。","傍人只道船行快，不道船中客更惊。"]},{"t":"涧上居人","f":"七言绝句","c":["跨涧作桥兼作屋，行人初到已泠然。","全家寝食淙琤上，韶頀声中过百年。"]},{"t":"留别南湖二首 其二","f":"七言绝句","c":["九重城里尘如海，只有南湖一片霜。","若向南湖谈世事，老夫只得去池阳。"]},{"t":"留别南湖二首 其一","f":"七言绝句","c":["老夫梦识南湖路，水槛山堂处处通。","若有新篇无告诉，不妨题写寄江东。"]},{"t":"留荆门蒙泉上三日无诗将去作二绝句谢之 其一","f":"七言绝句","c":["倚云上头寒碧下，三日团圆看似痴。","领略山灵无此客，与君何处更须诗。"]},{"t":"留荆门蒙泉上三日无诗将去作二绝句谢之 其二","f":"七言绝句","c":["我诗只在篮舆上，兀兀荒陂自语时。","坐看飞云行看水，此时无我更寻诗。"]},{"t":"病牙","f":"七言绝句","c":["去年胃口辞瓜果，今岁牙车怯稻粱。","饮食于身已无几，更须身世觅轩裳。"]},{"t":"病起","f":"七言绝句","c":["不分春风太厮欺，起来花絮满城飞。","可能不待诗翁出，直作堂堂取次归。"]},{"t":"皋亭山","f":"七言绝句","c":["西湖南北宝峰环，塔寺园亭碎点斑。","不似北关门外看，更无一物涴青山。"]},{"t":"读本朝史有感十首 其一","f":"七言绝句","c":["若讷希文受责均，前贤初岂有冤亲。","暮年颍上还惆怅，引得无穷射羿人。"]},{"t":"轿中听雨","f":"七言绝句","c":["急雨淙琤打轿檐，绿荷声里下湖船。","时时更把山矾嗅，岩桂香中八月天。"]},{"t":"钱唐道中望越州山","f":"七言绝句","c":["隔江东望越州山，七载重来喜破颜。","却数故人今几在，一襟清泪湿潸潸。"]},{"t":"铁笛亭","f":"五言绝句","c":["夜啸千崖裂，朝吟万象苏。","山人大自在，无泪捋君须。"]},{"t":"偶得二首 其二","f":"七言绝句","c":["雪中春到梅花觉，冰底水行人未知。","珍重天公好消息，通今通古更何疑。"]},{"t":"偶得二首 其一","f":"词","c":["水边杨柳秃?沙，路上寒梅噤未花。","欲识乾坤生物意，桑根麦子已含芽。"]},{"t":"宿云门寺赠张武子","f":"七言绝句","c":["绝怜雪屋张居士，日日空墙挂食箪。","吟到古人辛苦处，囊中不得一钱看。"]},{"t":"宿巴羊峡","f":"七言绝句","c":["夜榜巴羊听水声，江南幽梦到吴屏。","贺家湖上黄梅雨，四面荷香入画舲。"]},{"t":"晚荷","f":"七言绝句","c":["僛僛翠袖舞寒塘，无复当时婉婉妆。","荡子游娃俱不到，倚风摇月自生香。"]},{"t":"晦日出长安闸","f":"七言绝句","c":["长安堰口长安闸，一度经行一断魂。","不道秦川在何处，只惊行色近中原。"]},{"t":"曹桥","f":"七言绝句","c":["听得鸣鸠逐妇声，行人相顾各心惊。","夜阑云散天如洗，乞得曹桥一路晴。"]},{"t":"望三叠泉谷帘泉而不能至","f":"七言绝句","c":["只游玉峡并三峡，未到帘泉与叠泉。","少日跻攀今老矣，且随筋力度残年。"]},{"t":"梅","f":"七言绝句","c":["只消数点著枯枝，不用东君一叶垂。","任是雪深烟更密，清香依旧世人知。"]},{"t":"梅开次韵答叶教授二首 其二","f":"七言绝句","c":["春风一点暗惊梅，便有千花动地开。","却似德人方寸事，等间流向笔端来。"]},{"t":"梅开次韵答叶教授二首 其一","f":"七言绝句","c":["雨洗晴烘两行梅，朱朱白白尽情开。","不须更到东亭得，读罢君诗似看来。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其三","f":"七言绝句","c":["向来多士首何方，此学巍然道有光。","付与能言子程子，莫教章蔡更专场。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其二","f":"七言绝句","c":["雪中草草漫裁诗，沂国平生已可知。","今日功名付家婿，百花头上更何疑。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其八","f":"七言绝句","c":["江南官路接天开，五月长安赐第回。","若见门人旧题处，亦须披拂记曾来。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其五","f":"七言绝句","c":["五星高会记当年，笑语喧江夜不眠。","今日江头看独往，人生聚散亦堪怜。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其一","f":"七言绝句","c":["元祐真人第九春，玉颜惊喜识荆人。","如今凤质龙章士，又合抡魁作近臣。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其六","f":"七言绝句","c":["霜风策策鼓黄芦，满眼吴江旧去途。","梦到月明天阔处，夜深泥宿故城湖。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其七","f":"七言绝句","c":["夜醉巴河酒满船，晓餐湓浦浪掀天。","回头已作三年梦，应笑当时尚少年。"]},{"t":"淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其四","f":"七言绝句","c":["诸公奉诏选豪英，翰墨声名要老成。","谁敢一钱经卫尉，直须倾盖赠先生。"]},{"t":"脱叶","f":"七言绝句","c":["绿阴时节叶急飞，投分青芜更不疑。","横被蛛丝禁得住，舞风一片独多时。"]},{"t":"铜陵县步","f":"七言绝句","c":["二年三过铜陵县，欲采蘋花意自羞。","他日梦中应记得，浅山衔县水衔州。"]},{"t":"雪中得两联不能成篇","f":"七言绝句","c":["海峤风高云散卤，塞垣寒极地生硝。","雨花满坐来天女，宝唾乘空下阿娇。"]},{"t":"雪晴 其二","f":"七言绝句","c":["夜来露重谢嫦娥，造得清霜尔许多。","底事日高犹未落，看他青女嫁羲和。"]},{"t":"雪晴 其一","f":"七言绝句","c":["颠风围屋暖盈襟，满意成霜却做阴。","昨夜风休寒彻骨，晓霜呼日上平林。"]},{"t":"黄州赤壁下","f":"七言绝句","c":["杜牧谈兵语未公，都将事业付东风。","三江不见刘玄德，已觉曹瞒在掌中。"]},{"t":"善谑驿淳于髡墓上有木斜出口占","f":"七言绝句","c":["秦人磨斧闯山东，七泽青邱入梦中。","齐楚君臣正行乐，辟宫除道送金笼。"]},{"t":"富阳道中二首 其二","f":"七言绝句","c":["一带江流两岸山，玉花珠髻满云鬟。","一声鸣橹俱回首，小杜舟中醉眼看。"]},{"t":"富阳道中二首 其一","f":"七言绝句","c":["云破天开雪欲晴，橹声争出满江鸣。","牵绳直上高崖去，想见瞿塘百丈行。"]},{"t":"游云门山读亭中诗板拟丐使者以石易之","f":"七言绝句","c":["唐人诗板四十五，丽句亭中岁月深。","烦公丐我一碑石，与张万壑松风音。"]},{"t":"游白鹿洞书院","f":"七言绝句","c":["曾依岳麓听鸣泉，亦泛朱陵石鼓船。","所欠平生惟白鹿，暮年来此岂非天。"]},{"t":"雁汊望舒州山","f":"七言绝句","c":["归帆拂掠皖公山，一路青峨立翠鬟。","曾见刘郎射蛟日，插天旌旆照孱颜。"]},{"t":"集杜句为老母寿三首 其三","f":"七言绝句","c":["禁城春色晓苍苍，花气浑如百合香。","万岁千秋奉明主，南极老人应寿昌。"]},{"t":"新月","f":"七言绝句","c":["窥人半面出脩眉，斜傍船窗作意低。","已被江妃偷画得，一湾清影卧寒溪。"]},{"t":"睡起","f":"七言绝句","c":["春半閒窗午睡酣，梦馀瑶篆晚香残。","起来磨墨花盈砚，勾得东风上笔端。"]},{"t":"辑句招王国正四首 其四","f":"七言绝句","c":["万里相逢贪握手，蓬门今始为君开。","留连城郭今如此，有底忙时不肯来。"]},{"t":"辑句招王国正四首 其三","f":"七言绝句","c":["投老归来一幅巾，翛然三月闭柴荆。","固知贫病人须弃，客至从嗔不出迎。"]},{"t":"辑句招王国正四首 其二","f":"七言绝句","c":["青春欲尽急还乡，万里桥西一草堂。","富贵功名何足道，先生有道出羲皇。"]},{"t":"辑句招王国正四首 其一","f":"七言绝句","c":["璧门金阙倚天开，兴罢张帆载酒回。","日看省曹阍者面，鞭笞鸾凤相追陪。"]},{"t":"酬答复州叶教授 其一","f":"七言绝句","c":["先生来赴泮林期，正是寻花问柳时。","偷把春风舞雩曲，蒹葭江上避人吹。"]},{"t":"酬答复州叶教授 其四","f":"七言绝句","c":["竟陵寒尽转春风，坛杏株林淑气通。","惆怅江陵红白树，年年幽独伴邻翁。"]},{"t":"酬答复州叶教授 其二","f":"七言绝句","c":["象环章甫古冠衣，解佩江边结伴嬉。","应共游童春浴罢，咏歌乔木错薪辞。"]},{"t":"酬答复州叶教授 其三","f":"七言绝句","c":["陆子泉头春水生，一瓯新乳雪花明。","唤回明照山前梦，起对庭花忽自惊。"]},{"t":"槠州路口小雨诗","f":"七言绝句","c":["三十年前过此时，一双青髻绾青丝。","如今旧雨犹相记，只傍星星白发吹。"]},{"t":"疑雨","f":"七言绝句","c":["泉声㶁㶁转山隈，错认山头急雨来。","赤道千寻上青壁，恍如飞电掣云开。"]},{"t":"嘲青女","f":"七言绝句","c":["乾地成霜水地冰，薄冰顽白厚冰清。","阿婆老去铅华少，西抹东涂画不成。"]},{"t":"题屏风墨梅二首 其二","f":"五言绝句","c":["天上和羹事，巢由不忍闻。","疏花将瘦影，閒卧一溪云。"]},{"t":"题屏风墨梅二首 其一","f":"五言绝句","c":["一段西山雪，中含太古梅。","无香亦无色，免被百花猜。"]},{"t":"题鹿门山绝顶升云亭","f":"七言绝句","c":["上到山头十八盘，贪高不计足心酸。","年来学力荒唐甚，羞向升云顶上看。"]},{"t":"赠刘正将","f":"七言绝句","c":["柳亭门户劣三间，诗伯封疆自一寰。","批判秋风勾夜月，抨弹淮水荐钟山。"]},{"t":"赠彭术士 其一","f":"七言绝句","c":["卷舒湖水槛前帘，开阖山光舍后檐。","幸有湖山供卧起，莫将世味较酸甜。"]},{"t":"赠彭术士 其二","f":"七言绝句","c":["涢水春深战未停，庐山秋老梦方宁。","与君岂有平生怨，挽向兵间说汗青。"]},{"t":"壕头入衡山界","f":"七言绝句","c":["乱木林中微有路，两山峡里欲无天。","前头似向夔州去，应有西川未了缘。"]},{"t":"瞿唐峡","f":"七言绝句","c":["家住东溟狎巨涛，今年三峡试容舠。","瞿塘关下惊危甚，一席巴天浪许高。"]},{"t":"一日姑苏怀古","f":"七言律诗","c":["披山临水结层城，髣髴当年霸主情。","鱼满松江船似栉，田连震泽稻如京。","巍巍二老辞周箓，碌碌诸孙竞晋盟。","可但馆娃能败国，阿员三世只谈兵。"]},{"t":"丁教授家猫狗皆相乳二首 其二","f":"七言律诗","c":["血人于牙犬政猛，杀鼠如邱猫事狞。","邻子忽如亲子爱，人情何似物情平。","再三仁者须存勇，万一天资与习成。","恐被麋麑邀作友，或遭鼠弟□为兄。"]},{"t":"丁教授家猫狗皆相乳二首 其一","f":"七言律诗","c":["周郊奉犬用刑樽，尧蜡迎猫似捕神。","直是苏公比台谏，未知韩子喻家人。","鹰鹯化作鸾将凤，獬廌移成驺与麟。","煦煦徐徐何必善，使知刚毅有深仁。"]},{"t":"七夕谢孟漕品味","f":"七言律诗","c":["金井琅玕戒女功，木桃瓜李奏民风。","天河夜酌尊罍满，帝子秋盘饼饵丰。","戢戢玉莲参藕艇，忻忻火枣会梨宫。","星轺著意来看客，不与寻常乞巧同。"]},{"t":"七日吕城守闸","f":"词","c":["官闸嶒?昼闭涂，商船嘈囐夜衔舻。","卧听篙子湾湾月，坐待州家急急符。","石罅漏泉鸣锦瑟，篷窗筛雨落玭珠。","梦魂不受重门隔，自著斑衣过练湖。"]},{"t":"九日喜陈一之提刑至龙山","f":"七言律诗","c":["闻道西征使者来，满城风雨菊花开。","唤回乌帽千年梦，惊倒龙山百尺台。","病叟旧痾初去体，元戎新酝恰浮醅。","篱边更有休官令，人事天机亦异哉。"]},{"t":"九月呈运使卢检院","f":"七言律诗","c":["法官蒇事三灵格，山国休工万宝成。","虏使此时心暂展，丽谯高处眼增明。","搴帷正在煎萸俗，缀席何妨伴菊倾。","此会明年公莫问，赐来应有一枝荣。"]},{"t":"二十一日柘龙桥道中","f":"七言律诗","c":["早禾登架晚禾青，雨后官塘处处平。","山马未明行木彴，水牛亭午卧深坑。","人家总在林间住，生计惟凭陇上耕。","青嶂夹田田夹涧，翠围屏里万竽笙。"]},{"t":"二十九日出暗门循城至北关登舟","f":"七言律诗","c":["篮舆出郭转墙隈，欲老芙蕖尽意开。","天气已凉犹索热，官身得去未忙回。","舟行何物非诗句，病后无情是酒杯。","一笑团栾今在目，细挑灯火话蓬莱。"]},{"t":"二十二日入荆门界","f":"七言律诗","c":["四望亭前粉雉明，百栏桥上竹枝横。","荒荒白日春将晚，渺渺黄冈草未生。","独客更无杨柳伴，远村时见李花惊。","白碑南路翻堪意，不恨冲泥踏水行。"]},{"t":"二十八日行香即事 其一","f":"五言律诗","c":["晓市众果集，枇杷盛满箱。","梅施一点赤，杏染十分黄。","青李不待暑，木瓜宁论霜。","年华缘底事，亦趁贩夫忙。"]},{"t":"二十八日行香即事 其二","f":"五言律诗","c":["柳岸濛濛湿，沟波点点跳。","窗槽斜溜涌，轿顶碎声飘。","村担果争市，山桅花满桥。","愁听新使客，墟里说萧条。"]},{"t":"二日至襄阳诗卷为偷儿持去","f":"七言律诗","c":["华黍诗亡更自珍，银杯羽化未须嗔。","不然雷电将天上，或者浮沉自水滨。","郑老本无毡可守，虎头政恐画能神。","苦心只道无人爱，何物偷儿却可人。"]},{"t":"八日丹阳相遇","f":"五言律诗","c":["舟楫庭闱近，衣裳步武轻。","逆风犹作态，寒日为开晴。","独客天边住，全家水面行。","今朝逢一笑，此乐冠生平。"]},{"t":"八日泊故人亭观二水合流处","f":"七言律诗","c":["各自南来共北流，孤亭直下对中洲。","湘流几日发阳朔，潇水伴吾离永州。","预戒篙工泊江口，急穿巾子上山头。","哦诗未了寒催客，却下篷窗唤解舟。"]},{"t":"十七弟生日用其韵","f":"七言律诗","c":["寿星合在角亢旁，为尔来临翼轸乡。","日向绣床添永算，云纵书观发嘉祥。","修程九万开荣路，曲礼三千阅寿觞。","冬弟春兄同此日，天教鸿雁自成行。"]},{"t":"十七弟生朝","f":"七言律诗","c":["至日阳生万事新，阿连于此庆生辰。","一天云物皆和气，满市人家作贺宾。","寿算暗随宫线长，科名行逐地雷伸。","病夫已学陈根退，只愿庭前玉树春。"]},{"t":"十九日至都门次巩仲至立春日见寄韵","f":"七言律诗","c":["客子沙头饮饯时，美人溪上正题诗。","栗斋寒尽相思早，竹阁春闲拜赐迟。","别后著书逾汗马，闲中读易见灵龟。","何由洗砚居兄左，快斧麾天看一斯。"]},{"t":"十九弟生日 其二","f":"七言律诗","c":["茧丝成綍夏初新，柳色如袍尚带春。","已见出墙添笋稚，即看调鼎长梅人。","书随雁序升秋汉，研拂龙旗对晚宸。","勉为家门成胜事，六枝仙桂一株椿。"]},{"t":"十五弟生日","f":"七言律诗","c":["合宫雷雨下江城，重把贤书旧贡升。","入月穿天搜伏兔，抟风击水化新鹏。","当年吉梦浑家喜，今日成名望汝能。","千岁灵龟须自养，朵颐无用酒如渑。"]},{"t":"十五夜雪","f":"七言律诗","c":["幸自封姨不敢嗔，放教月姊伴游人。","不知滕六来何许，忽与天官竞此辰。","莲焰扑残惟种李，金波捲尽只铺银。","玉皇应是怜尧父，不做元宵已四春。"]},{"t":"十六弟生日 其三","f":"七言律诗","c":["艾花开过天中节，桂树飞来月上弦。","唤起西堂春草思，吟成小雅杖华篇。","庭闱心事关儿子，场屋声名有岁年。","好把文章收富贵，却将功行作神仙。"]},{"t":"十六弟生日 其二","f":"七言律诗","c":["一弦光上五云端，恰共乘弧势一般。","畴昔熊罴和梦到，只今雕鹗待秋抟。","红榴色借丹枝重，碧藕香摇翠袖寒。","堂上双亲虽白发，情怀偏向试闱欢。"]},{"t":"十六弟生日 其一","f":"七言律诗","c":["长庚飞下祝融墟，瑞入清台夏五书。","八荚花开羲叔历，一枝桂长羿妃居。","南薰解养秋风鹗，梦泽能生北海鱼。","看上扶摇龙尾道，曼声传唱绕周庐。"]},{"t":"十六夜州宅观月","f":"七言律诗","c":["青天碧海桂光流，已是人间万古愁。","野阔江深那向楚，霜深露冷更逢秋。","此时此地俱清绝，无酒无诗得索休。","太守尚嫌高兴少，捲云飞雨架层楼。"]},{"t":"十日发祁阳 其一","f":"七言律诗","c":["自矜重九苦吟处，写出浯溪真画图。","安排秀句待石鼓，指点江神迎綵舻。","小雨已休朝复作，寒流忽涨夜仍枯。","篷声瑟瑟滩声滑，应伴先生著句无。"]},{"t":"又中秋小雨","f":"七言律诗","c":["天生明月照秋空，人把鲜晴候岁功。","可忍浮云来镜里，更堪风雨落庭中。","旌旗踏浪惊吴俗，灯火连街见楚风。","江海归来心未稳，犹疑醒眼是朦胧。"]},{"t":"又中秋沿檄新昌道中有怀二首","f":"七言律诗","c":["乱山深处过中秋，客里今年分外愁。","坐想鸰原挥兔翰，遥知鹤发念貂裘。","一身四处为肝胆，有月无人与献酬。","急唤老兵同浊酒，强排孤愤作清游。"]},{"t":"又月出次韵","f":"七言律诗","c":["觥船老去不能空，诗律衰来渐少功。","此夜轮边谁得句，一壶花下偶成中。","光分少皞金天露，气挟蓐收阊阖风。","只恐嫦娥须自悔，何如云里放朦胧。"]},{"t":"又代作 其二","f":"七言律诗","c":["羲仲量沙数砌蓂，甘公聚米算周星。","无边海福兼山寿，不尽天英与地灵。","翰苑文章看李白，岩廊风度待张龄。","春风万里岷江水，吹作香醪尽意青。"]},{"t":"又代作","f":"七言律诗","c":["绛帷犀镇绣帘低，翠竹龙香锦帕齐。","百柂琼艘倾竹酝，千年眉寿辑萱闺。","堂东已见床堆笏，庭下行看玉满畦。","岁晚逢春知有意，天教齯齿受新褆。"]},{"t":"又代作","f":"七言律诗","c":["新年轮遍列星名，却到龙头第一星。","梦泽东风吹丽曲，锦江春浪涨芳醽。","月鸾云凤挥才藻，日鹤天龟与寿龄。","此会明年应更好，长安花里醉还醒。"]},{"t":"又代作 其一","f":"七言律诗","c":["风收十四叶尧蓂，云捧三千岁寿星。","人讶绣鸾淹彩翼，天教纹鶒效殊灵。","中书将相无穷考，上古春秋不计龄。","长见烛花香帕畔，小桃红嫩柳新青。"]},{"t":"又代庠孙","f":"七言律诗","c":["春风建邺花如锦，社日秦淮酒似油。","绣阁相传住针线，高堂有喜送觥筹。","兔经三夜光长好，燕入新年语不休。","商略重闱何许寿，八千才是一春秋。"]},{"t":"又用韵酬赠潘杨二首 其一","f":"七言律诗","c":["物物当前总是诗，遇丝成瑟竹成篪。","止呼大义周王泽，蔽以无邪孔氏思。","屈贾词悲变弁凯，齐梁格靡陷崔绥。","欲回温厚千年教，须仗诗翁为一麾。"]},{"t":"又次王醇甫闻人主簿二首 其一","f":"七言律诗","c":["眄柯陶令喜归园，瑩玉灵均恨变丹。","朝饮夕餐和露摘，东篱南岫带云看。","仙方旧说南阳寿，异色新添霅水寒。","谁道王郎偏爱竹，也来同枕效今潘。"]},{"t":"又次韵邓汉卿秀才送行","f":"七言律诗","c":["春风不疗鬓边霜，闲处输君笑我忙。","衮衮悬河烦卒吐，疏疏冷锉赖于湘。","去钻芸帙翻成蠹，飞下芹泥只愿颃。","鉴水旧游零落尽，相逢犹忍话髯郎。"]},{"t":"又次韵吴少保游雄楚楼及渚宫","f":"七言律诗","c":["红旗绣额上城头，菱叶荷花下小舟。","遵渚夷犹荡佳月，倚天突兀对高秋。","坡公句里东南水，杜老诗中西北楼。","点化山川一刀匕，风流从此说吾州。"]},{"t":"又次韵杨秘书送行","f":"七言律诗","c":["设矩陈绳劝蹈中，雕龙炙輠戒多穷。","有谁心肯明斯语，无限人知敬此翁。","信有德隅当并进，可能性地独幽通。","相分便作相逢计，此事它时验庳崇。"]},{"t":"又次韵沈告院送行二首 其二","f":"七言律诗","c":["江头水落雁初下，江上鱼肥酒可中。","秋浦到时应正好，昔贤题后恐难工。","三年禁直消长日，六月脩廊饫午风。","天上素餐吾已愧，更来闲处理渔筒。"]},{"t":"又次韵沈告院送行二首 其一","f":"七言律诗","c":["前年倚席湘山下，曾得新篇胜玉葩。","今日题舆秋浦上，又烦佳句溢琼华。","云霄策足君方驶，风雨论心我未涯。","正向齐山插黄菊，遥知已对紫薇花。"]},{"t":"又次韵罗商卿七夕雷雨","f":"七言律诗","c":["早秋初夜暗凉生，门巷欢呼见物情。","时节自令儿女爱，年华潜遣鬓毛惊。","一声霹雳开银汉，万丈云涛下太清。","析木津头倾见底，鹊桥从此不须营。"]},{"t":"又和毛子和郑荐玉","f":"七言律诗","c":["长腰如玉稳如金，千里西城待一霖。","忧国元戎真沥血，还家倦客更关心。","卧听檐吹长疑滴，起看江云只愿阴。","但得街头官酒贱，速呼毛郑与同吟。"]},{"t":"又病起送春","f":"七言律诗","c":["睡过珍林十日红，起看阳艳欲成空。","有情尽付莺和蝶，无恨堪嗔雨与风。","原隰望中青一色，栏干凭处意无穷。","衰翁晚悟人间事，春去春来岁岁同。"]},{"t":"又赋","f":"七言律诗","c":["属玉风前藕叶香，残蝉声里柳枝黄。","生前天遣耕云土，身后人来问雪堂。","樊口战船旗似锦，黄坡突骑剑如霜。","先生傥有归来梦，更觉春江雨后忙。"]},{"t":"丈人任知县生朝","f":"七言律诗","c":["老梅坡底万花黄，未问重阳且少阳。","华岳金天钟宝器，屏星初月照琴堂。","阿连句好珠躔聚，文度归来玉树香。","千岁易逢难此会，明年湖海却相望。"]},{"t":"三月一日入襄州界先寄吴待制二首 其二","f":"七言律诗","c":["儿时梦到汉南州，四十头颅未省游。","此段风流愧人物，今年行役藉君侯。","仲山甫有遗墟在，诸葛公存旧事不。","欲借蹇驴驮醉帽，从公一一访前修。"]},{"t":"三月一日入襄州界先寄吴待制二首 其一","f":"七言律诗","c":["明德宫中大练衣，风流小阮世人知。","断无流水游龙梦，只有珊瑚碧树词。","天上仙人持紫橐，边头武吏簸红旗。","男儿自要粗官作，肯被青云富贵欺。"]},{"t":"三次刘寺韵赋张以道新居与约斋夹湖相望 其一","f":"七言律诗","c":["寒绿新轩对马头，陂南陂北□销愁。","合添渔艇两三只，时与约斋来往游。","攲枕孤鸿烟雨涨，钩帘宿鹭晓光流。","何时祭灶呼邻里，我欲题诗素壁留。"]},{"t":"三次刘寺韵赋张以道新居与约斋夹湖相望 其二","f":"七言律诗","c":["碧柳黄芦冷映门，荒陂寒水净涵村。","深深留殿朝常闭，肃肃行营夜不喧。","景似丘园宜避俗，事非风月总忘言。","平生故有闲吟分，何物堪酬造化恩。"]},{"t":"三次韵咏雪","f":"七言律诗","c":["初惊簌簌响虫书，稍觉霏霏入草庐。","直是谢娘工说似，未腾欧叟不言如。","相投最惜衣裾片，恋别尤怜瓦缝馀。","谁见道山新霁后，嫩寒微峭日光徐。"]},{"t":"三弟校尉生日用去腊见寿韵","f":"七言律诗","c":["八千尧历畀秋春，万里嵩高下甫申。","儿女只今多似栉，弟兄他日老于亲。","共誇戏綵随鸠杖，不羡横挝倚凤宸。","看取天台游观主，前衔虚作汉朝臣。"]},{"t":"三送陈沅江","f":"七言律诗","c":["苦死相留不疗饥，再三相送只添诗。","金兰去我方嫌速，襦裤催公莫恨迟。","碧海声名无右者，玉霄歧路合东之。","未应白发清溪上，长傍孤篷理钓丝。"]},{"t":"上元","f":"七言律诗","c":["月华未上鼓声喧，又向山阴过上元。","五岁镜湖才一熟，今年灯市始应烦。","留连昼景通三夜，呼吸阳和达九门。","游客不知千古意，看人看火漫奔奔。"]},{"t":"上泉","f":"七言律诗","c":["阴崖古木挂藤萝，下有神龙阅世多。","荇带水衣闲自舞，鯈鱼石蟹戏相过。","岂知霖雨为何事，自喜红尘不到他。","落叶满林迷去路，牧童相引到山阿。"]},{"t":"上冢还过方桥","f":"七言律诗","c":["一番新火试新茶，又向方桥记岁华。","草色前头见江树，桑林多处是人家。","拓开白鸟天边眼，背尽红尘脚底沙。","临老不知来几度，只看豆麦不看花。"]},{"t":"丫头岩","f":"五言律诗","c":["三十年前过，吾方似此山。","山容今尚丱，吾鬓久成班。","羞把娉婷嫁，长垂婑堕鬟。","黄尘乌帽底，愧汝若为颜。"]},{"t":"久斋诗为南康赵司户作","f":"七言律诗","c":["岁寒始见松将柳，道远方分骥若驽。","凿井为山新意气，断干穿石老工夫。","重湖水作葡萄涨，五老云成锦绣铺。","万古千秋模不尽，几家文集几家图。"]},{"t":"习家池旧临官路今路改而东池半入驿吏引自桑林中往观因记所见","f":"七言律诗","c":["步入荒林问习家，江吞古岸入平沙。","枯池旧岁犹生藕，病柳新年尚著芽。","草上醉人眠未醒，桑间游女笑相遮。","东风倦客生情性，伫立残阳看落花。"]},{"t":"卫州东湖","f":"七言律诗","c":["自笑知州百不知，近他池馆未曾窥。","主人正可今为客，和议初成恰是时。","草色茸茸花覆座，波光滟艳酒浮卮。","留连枉是凭栏久，洗得当年了事痴。"]},{"t":"大人生日 其二","f":"七言律诗","c":["欲系银章望日边，先裁綵服拜亲前。","自家及国欢情一，以顺移忠喜事连。","兔管鸾笺松字日，金风玉露菊花天。","十分领取无穷寿，否极如今合泰然。"]},{"t":"大人生日 其一","f":"七言律诗","c":["明日君开祝寿场，今朝臣捧寿亲觞。","愿亲有俾昌而大，与国无穷禄尔康。","台上菊迟今始绽，堂前桂晚后弥芳。","仙翁作计深长在，待看孙曾笏满床。"]},{"t":"大人生朝六首 其一 安世","f":"七言律诗","c":["一秋六诰入于门，总是君恩与父恩。","拔起单贫新氏族，训开痴騃小儿孙。","于今教养功都就，畴昔乡闾道愈尊。","乐事满怀无一欠，只消长寿看仍昆。"]},{"t":"大人生朝六首 其二 宜孙","f":"七言律诗","c":["晓锵环佩谒仙灵，退著班衣戏宁馨。","帝所已开天佑节，新闱又拜老人星。","为臣为子真逢运，斯万斯千并与龄。","圣主萝图长奕奕，仙翁华发再青青。"]},{"t":"大人生朝六首 其四 容孙","f":"七言律诗","c":["一年好景是重阳，萸紫樨红菊更黄。","可但初旬堪落帽，不□二九再飞觞。","芝书况有重重庆，桂种仍传衮衮芳。","岁岁年年秋色里，玳筵红烛醉风光。"]},{"t":"大人生朝六首 其三 寅孙","f":"七言律诗","c":["岧峣丹阙六龙飞，浩荡鸿私下九围。","花结初颁红锦帙，宝香新拜绿荷衣。","未曾贺刺周闾里，又报升柴享禁闱。","千岁几番蒙帝泽，一年两度被恩辉。"]},{"t":"大人生朝六首 其五 康孙","f":"七言律诗","c":["隔江遥望小蓬莱，满眼风光入寿杯。","涌起涛江为玉酒，泻开东海作金罍。","山龙恰为供香兽，桥鲤真堪截锦腮。","雁字满天霞正赤，染成诗轴胜于坯。"]},{"t":"大人生朝代诸儿五首以春风花草香为韵 其一","f":"五言律诗","c":["何物堪为寿，南华有大椿。","根株天地远，枝叶岁时新。","十倍大彭国，百分清渭滨。","周星八千度，才是一番春。"]},{"t":"大人生朝代诸儿五首以春风花草香为韵 其五","f":"五言律诗","c":["何物堪为寿，春山鹤算长。","云边风驭稳，松上露巢香。","顶浴丹砂润，翎梳白玉光。","宝图双象转，长在寿星傍。"]},{"t":"大人生朝代诸儿五首以春风花草香为韵 其二","f":"五言律诗","c":["何物堪为寿，巢龟碧玉筒。","龙洲多藕叶，上蔡足萧丛。","日月供呼吸，乾坤共始终。","年年冰冻解，绿发戏春风。"]},{"t":"大风中登长桥","f":"七言律诗","c":["又拖筇杖过垂虹，粉柱丹梁五十洪。","云气深深笼薄日，波声浩浩鼓长风。","客船破胆经塘石，渔艇轻生逐钓筒。","欲访三高无处问，悠悠千古见冥鸿。"]},{"t":"大雨","f":"七言律诗","c":["闲里光阴已自娱，近添衰病更宜居。","罗禽乐甚无宾客，庭草欣然罢吏胥。","一霎阴风催下箔，满堂流水唤开渠。","家童莫笑先生急，雨过先生缓有馀。"]},{"t":"大雪同官皆不入独坐道山简南湖张直阁","f":"七言律诗","c":["久矣招渠不受催，忽然过我已佳哉。","更于群玉峰峦里，拣得孤吟时节来。","入竹叶间添茗供，点梅梢上献诗材。","个般清绝今谁有，未必南湖此日开。"]},{"t":"小雨","f":"五言律诗","c":["小雨散炎毒，微风生早秋。","清凉人意足，厌浥草光浮。","夜枕梦新熟，晓窗梳不收。","茅栏听好语，香稻起西畴。"]},{"t":"小塘道中小雨二首 其二","f":"五言律诗","c":["隐隐轻雷动，昏昏野市迷。","嫩云时绽日，暖雨半含凄。","时节新装束，人家小鼓鼙。","晚来扶路看，往往醉如泥。"]},{"t":"小塘道中小雨二首 其一","f":"五言律诗","c":["元日暄如许，新春气未齐。","悬知当作雨，多谢不成泥。","头有高低坂，人如上下梯。","更晴三四日，可以到湘西。"]},{"t":"不出","f":"七言律诗","c":["老子年来惊五馈，闭门不出动经旬。","谁家花有倾城色，何处园无持酒人。","直以故书消遣日，短于佳句柰何春。","东君似欲相料理，柳外风来絮满身。"]},{"t":"中秋月","f":"七言律诗","c":["素娥行处与谁同，玉斧修成几许功。","空里若安丹桂木，云中应有白银宫。","蟾行万里惟三足，兔满千山望一雄。","海阔天宽无处问，看渠朝暮自西东。"]},{"t":"中秋新昌道中有怀","f":"五言律诗","c":["今夜山阴月，家庭想共看。","霜毛明寿鹤，雾鬓湿柔鸾。","北望江湖迥，南瞻屺岵寒。","赖凭双去雁，早已报平安。"]},{"t":"丹阳感旧","f":"五言律诗","c":["东来复西去，却数十三年。","三过丹阳县，俱乘万里船。","半生行役里，两鬓客愁边。","属玉沧波上，清标倍炯然。"]},{"t":"为吴司户作瓮天","f":"七言律诗","c":["笔端随意出洪纤，康俗山前自在禅。","已把屋来嘲作瓮，更将诗去谄为天。","蛆浮蠛舞无多子，鹍运鹏游即大千。","敢向时人称万卷，不妨李渤但如拳。"]},{"t":"为狄氏题","f":"七言律诗","c":["漭苍洲边缚苇亭，百年朝暮看云生。","月光破处藕花舞，雨意来时蒲叶鸣。","归艇欲迷宵路重，捲帘忽散晓风清。","已同苍狗俱无意，岂有江鸥更用盟。"]},{"t":"五日常州借闸","f":"七言律诗","c":["踏车如市水如金，守闸如城不放人。","共倚河渠通北使，可怜膏泽养边臣。","平生自计更蓑笠，此日何颜玷搢绅。","欲换小舟跳堰去，沙边渔子得相亲。"]},{"t":"五月七日乞池州添倅得请","f":"七言律诗","c":["群玉峰前罢校书，九华山下试题舆。","三年饱共铅黄语，一日去从朱墨居。","秋浦谪仙临赋后，齐山小杜醉吟馀。","薄才渐愧风流地，茧纸新抄雪不如。"]},{"t":"以琴高鱼茶芽送范蜀州","f":"七言律诗","c":["溪上幽人拾旧查，洞中丁户采新芽。","欲乘赤鲤惭仙骨，自瀹霜毫爱乳花。","莋路跨骡胜五马，邮筒得酒散双衙。","武夷道士知君否，正拥风鸾里月茶。"]},{"t":"元夕刘知录招饮","f":"七言律诗","c":["曾吹藜杖到蓬莱，亲见银潢铁锁开。","析木津头排列宿，鳌山脚下走轻雷。","荒城夜雪欺行李，画角晨霜送落梅。","邻舍相呼同酒盏，也教人道上元来。"]},{"t":"元日用前韵","f":"七言律诗","c":["元日今年分外寒，先生坚卧正如山。","乡闾草草兵戈外，雨雪栖栖道路间。","儿女有情催我起，杯盘无绪笑人悭。","何因得似江城雁，未转东风已北还。"]},{"t":"六日寄镇江马侍郎大同","f":"七言律诗","c":["十四年前楚水傍，碧油幢下拜辉光。","鲋鱼踯躅遵行潦，龙马腾凌出大荒。","珥笔南宫扶日月，横戈北府控升阳。","冷官只有酸寒分，又把藜灯照檗黄。"]},{"t":"六叔父生朝三首 其三","f":"七言律诗","c":["百摺榴花照画筵，八千椿历记遐年。","东公西母朱颜老，玉女金童綵服鲜。","梅雨涨添春色酒，麦秋黄起寿炉烟。","铜壶未下三更水，犹是清和四月天。"]},{"t":"六叔父生朝三首 其二","f":"七言律诗","c":["夷惠之间得趣多，天教弥月占清和。","门当午市心如水，发插秋霜脸自酡。","雨洗竹香侵瑞鸭，风翻荷润入杯螺。","欲知寿算长多少，楼外西江万里波。"]},{"t":"六叔父生朝三首 其一","f":"七言律诗","c":["拂拂南薰入燕堂，兽炉清润酒尊凉。","筵开汤饼麦初熟，綵结茶花丝正香。","翠竹有孙添夏笋，红榴能笑发春妆。","都将造物无穷景，来与仙翁献寿觞。"]},{"t":"六叔母生日 其一","f":"七言律诗","c":["千岁光阴二十停，一停才向此时盈。","律筒又报三阳近，历草还飞四荚轻。","冉冉春盘行细绿，泠泠臈盏泻空清。","不须更煮囊中药，息气存神自久生。"]},{"t":"六叔母生日 其二","f":"七言律诗","c":["已传春日在春前，诞日欺春又占先。","百面玉盘檠菜缕，两行红烛罩沉烟。","自从梅里迎王母，直到荷时庆老仙。","拦住东风头与尾，中间和气一千年。"]},{"t":"六叔母生朝","f":"七言律诗","c":["香梅细柳竞芳辰，预报新年两日春。","未得犀盘传菜缕，且看玉盏泛松仁。","东风衮衮添孙竹，南极双双照寿椿。","正是门阑多喜日，乘龙娇客翠袍新。"]},{"t":"六雪诗用前韵寓六字 其一","f":"五言律诗","c":["点点多难赛，蚩蚩势欲平。","群排风鹢退，深掩烛龙生。","乡混群庬吠，军喧乱鹜声。","光阴乘岁暮，威令极施行。"]},{"t":"六雪诗用前韵寓六字 其二","f":"五言律诗","c":["天宗兴岁事，滕叟盛威神。","乐羽朱成素，宫墙旧变新。","周爻方用坎，燕律遽生春。","花阵连天出，欢回合宇人。"]},{"t":"又中秋诗 其一","f":"七言律诗","c":["去年客里念庭闱，今日尊前捧寿卮。","乐事赏心仍有月，好天良夜可无诗。","秋原绝粒真成旱，俚俗烧灯不负时。","一笑难逢须自庆，几人对酒得开眉。"]},{"t":"内子生日 其三","f":"七言律诗","c":["人间十八最风流，更占新年第一筹。","北梦南云春渐暖，星桥火树夜初收。","舅姑未老椿松固，儿女成行璧玉稠。","但得长年同饱饭，其他万事更何求。"]},{"t":"又中秋诗 其二","f":"七言律诗","c":["烟清露冷月明中，无古无今此夕同。","大地山河归影里，白银宫阙上天东。","人情可是随时别，酒盏真堪对影空。","来岁相逢应更好，丹梯高处独乘风。"]},{"t":"内子生日 其一","f":"七言律诗","c":["去岁亲前捧寿杯，如今万里独西来。","遥知此日怜儿妇，应抚南枝问雪梅。","百尺灯山初转眼，一卮春酒欲酡腮。","愿言尊幼俱彊健，归著斑衣伴老莱。"]},{"t":"内子生日 其四","f":"七言律诗","c":["居士新年六秩来，细君初庆绮筵开。","朱颜拂拂生银勺，华发鲜鲜上玉台。","女嫁男婚成次第，殃销祸散到耆鲐。","高堂一曲斑衣舞，我唱君随作老莱。"]},{"t":"内子生日 其二","f":"七言律诗","c":["东风吹草未成花，物色相看意已嘉。","游女尽从灯夕出，家人重向寿辰誇。","层层膝下孙枝长，衮衮天边帝綍加。","欲和晏公延寿曲，红鸾紫凤劝流霞。"]},{"t":"内子生朝","f":"七言律诗","c":["寿杯同举寿闱中，此乐人人羡此翁。","满目芝兰如谢傅，齐眉宾主似梁鸿。","万枝灯过游尘息，三荚蓂飞淑气通。","正是春来好时节，柳梢微绿小桃红。"]},{"t":"分宜县","f":"五言律诗","c":["郭内清溪响，溪南列岫光。","林花千树白，屿柳一川黄。","野店明丹垩，邮签列短长。","先生心爱此，车过未须忙。"]},{"t":"劝醇甫酒","f":"七言律诗","c":["欲劝临歧酒一卮，若为啼笑若为词。","情怀作恶中年后，亲友相分久病时。","少壮岂知人寂寞，庭闱方待子飞驰。","饮阑百丈牵江去，挂起西川五色旗。"]},{"t":"午日","f":"七言律诗","c":["一杯聊解独醒哗，老眼犹明缠臂花。","煮角沈筒随地俗，赐衣题墨又天涯。","千年菖本须眉古，九蕊戎葵节纛华。","景物向人何所欠，明时不用赋怀沙。"]},{"t":"少保席间道襄州朋旧","f":"七言律诗","c":["持杯相向各言衰，忆得襄州未老时。","晓踏青山寻秀句，夜簪红药听新词。","只言坐上皆豪逸，谁信人间有别离。","头白归来堪自贺，独依雄楚看题诗。"]},{"t":"尤尚书挽诗 其二","f":"五言律诗","c":["旧学渊衷记，新阡玉色疑。","似闻形叹慨，未忍失容仪。","海道空赍志，西州只贮悲。","平生谢公愿，后世子云知。"]},{"t":"尤尚书挽诗 其一","f":"五言律诗","c":["今岁何迁次，乾坤失巨人。","老生啼坏木，后学叹迷津。","四海人才谱，三朝礼乐臣。","并将文献去，谁与觉斯民。"]},{"t":"忆宗道旧游","f":"七言律诗","c":["十八年前胜共饶，两青不借一枯焦。","狂挑药涧寻琼阙，醉踏经台问玉霄。","华顶云开千嶂露，赤城天近九霞飘。","祇今只羡蒲团稳，坐看双龙上石桥。"]},{"t":"方太君生日 其一","f":"七言律诗","c":["金鸭烟青蜡炬红，玉龟山上劝春风。","乍寒还暖花无数，似缺疑圆桂欲中。","八十又三人所羡，双瞳如漆寿难穷。","七千九百十七岁，始共椿龄一半同。"]},{"t":"方太君生日 其二","f":"七言律诗","c":["飘飘南极上明星，浩浩东风入翠醽。","春最好时才中半，人难学处是修龄。","已开棠树千枝锦，尚欠蓂花一荚青。","更愿儿孙添晚景，早收丹桂媚慈庭。"]},{"t":"方桥晚憩","f":"五言律诗","c":["归路方桥晚，年年此月情。","不知临老去，更得几番行。","浩荡东风阔，微茫远水横。","每来心自爱，未要世人惊。"]},{"t":"月台","f":"七言律诗","c":["小筑南台倚北亭，一方荆玉可云屏。","峡中暮雨尝疏月，秋后天河始见星。","初与羿妃为此会，自开夔子几千龄。","我虽不饮心先醉，坐汲寒光当渌醽。"]},{"t":"水仙花","f":"七言律诗","c":["意浓态远十洲人，岁晏天寒七泽滨。","奕奕云冠疑映月，僛僛翠带欲摇春。","梅稍枉为行人瘦，柳眼虚随酒市新。","林下水边风味永，弄珠谁见汉皋神。"]},{"t":"王少清归蜀不成复下鄂渚诗","f":"五言律诗","c":["行止不可计，别离当奈何。","赋归重作客，欲溯竟沿波。","湖上橘方熟，洲边鱼正多。","西山旧相识，不厌屡经过。"]},{"t":"王君行丈挽诗 其二","f":"五言律诗","c":["乐叟干将剑，锋铓凛不收。","之人独和厚，与世极沉浮。","淑气长三月，高怀自九秋。","洞门元不锁，依旧少从游。"]},{"t":"王君行丈挽诗 其一","f":"五言律诗","c":["春末乐叟去，秋初仍牧斋。","无谁问天理，有底厌吾侪。","简易逢人乐，虚徐触事谐。","忽逢孤绝处，千丈崒高崖。"]},{"t":"王君行丈挽诗 其三","f":"五言律诗","c":["房州迎主簿，惠我数行书。","恸哭王郎死，凄凉楚泽虚。","少将诗作剧，老共易同居。","比似曾居士，规绳更不疏。"]},{"t":"见雁","f":"五言律诗","c":["万古胡沙雁，衡阳到即回。","如何九日至，故作永州来。","节里他乡客，江边独夜桅。","吾亲应念我，烦汝到浯台。"]},{"t":"车驾还内大雪","f":"七言律诗","c":["万乘回辕入未央，六花迎驾舞康庄。","都人失喜瞻天仗，旱俗相呼候岁穰。","百局桥山方暴露，两宫长信正凄凉。","去年群玉题诗处，独倚栏杆泪几行。"]},{"t":"风雨望武昌岸","f":"五言律诗","c":["寒食今朝是，颠风半夜来。","自从天色暖，已遣客心猜。","雨打洲容沐，烟笼水面灰。","孙郎将漫叟，相送到浯台。"]},{"t":"乐君启文挽诗 其二","f":"五言律诗","c":["艺应天王拜，名高月旦评。","一官娱晚暮，千载遇恩荣。","未许行畴昔，犹应得久生。","年来频见此，老泪不禁倾。"]},{"t":"乐君启文挽诗 其一","f":"五言律诗","c":["荆州十万户，惟我独知公。","皓皓峣峣甚，凉凉踽踽中。","平生尊骨鲠，到死讳雷同。","此士埋黄壤，何人立素风。"]},{"t":"代任阆州和人重午二首 其二","f":"七言律诗","c":["游龙蹴浪锦江高，节物惊人感二毛。","京洛承平真富贵，江湖风物叹萧骚。","荃芜有恨流千古，驽骥当年共一槽。","圣处相期君不肯，自煎明焰泣流膏。"]},{"t":"代任阆州和人重午二首 其一","f":"七言律诗","c":["灵符高挂辟方良，宝剂旁搜纳众芳。","穰穰人情随节变，冥冥古意与□长。","新裁白雪罗衣润，旋剥黄金角饵香。","尚想中流见荃棹，徘徊洲浦待巫阳。"]},{"t":"代作五首 其五","f":"七言律诗","c":["孟尝当户三千客，镇恶成名百二关。","天以高名钟是月，人于季孟得其间。","八风巡日开云荚，半壁腾空映雾寰。","共祝星郎千岁喜，天孙早晚渡银湾。"]},{"t":"代作五首 其四","f":"七言律诗","c":["流霞元是吾家饮，生日曾供老杜诗。","色借榴心芳露重，香分荷气碧泉滋。","重闱永夜宜开酌，六礼今年看结缡。","可但椿长并桂永，灵妃萧史寿无期。"]},{"t":"代作五首 其三","f":"七言律诗","c":["苍龙元住五云东，此日黄昏却正中。","琴瑟铜壶添水箭，翩翻珠户记桑蓬。","上弦月色如银白，南极星光似烛红。","岁岁年年尊酒畔，小荷香雾绿槐风。"]},{"t":"代作五首 其二","f":"七言律诗","c":["一点阴机初昼迟，十分阳德正开离。","后王诰命章施日，天地文明盛丽时。","历草自生萧相叶，桂花须占郤诜枝。","千钟顿止真堪畏，万石他年更不疑。"]},{"t":"代作五首 其一","f":"七言律诗","c":["昼漏如今天共永，寿辰于此数难量。","三千花实桃犹小，五日春秋木未长。","羲宅巧占尧火正，娥宫新学羿弦张。","两轮朝暮无穷照，可怕金乌玉兔忙。"]},{"t":"代宜孙","f":"七言律诗","c":["潭潭厦屋照春天，初作生申第一筵。","清畅惠和三月四，炽昌耆艾万年千。","窦郎植桂枝枝茂，荀里生龙个个贤。","汲井餐葵同此润，捧觞来赋从孙篇。"]},{"t":"代赵丞相作黄尚书挽诗三首 其三","f":"五言律诗","c":["力小惭形渥，心同傒栋隆。","忠能当世事，信可沃宸衷。","长往公何遽，孤鶱我最穷。","老来难得泪，独为洒西风。"]},{"t":"代赵丞相作黄尚书挽诗三首 其二","f":"五言律诗","c":["讲读真无敌，忠诚素有孚。","谈经兼体用，论事极精粗。","日已升旸谷，天方冒海隅。","甘盘当保义，岂料岁年徂。"]},{"t":"代赵丞相作黄尚书挽诗三首 其一","f":"五言律诗","c":["剑阁重来日，瀛洲仅阅旬。","一从充保傅，五见易冬春。","作圣工夫久，膺图岁月新。","九重深悼处，早晚付经纶。"]},{"t":"冬至前简陈正己李季允","f":"五言律诗","c":["节物吹葭近，乡闾送篚频。","驩虞倾一市，憔悴独三人。","驿破风搜屋，船低月暗津。","吾亲于越外，日夜鬓毛新。"]},{"t":"冯元素挽诗 其一","f":"五言律诗","c":["戎服开清洛，儒书谒阜陵。","一朝官御晚，平日壮心冰。","此士归来夜，何人说中兴。","秋来原上草，萧索见风棱。"]},{"t":"包山送辛大卿知福州","f":"七言律诗","c":["楼头尊酒送将行，楼下江潮意未平。","漠漠南天垂雨脚，阴阴长夏作秋声。","杜陵恋阙心应苦，楚客思君泪合倾。","莫倚轻红宜重碧，男儿报国在尊生。"]},{"t":"卢似之从道子行","f":"五言律诗","c":["昔我为行客，烦君作好诗。","今吾仍是主，送子得无辞。","文赋须勤作，经书莫暂离。","天资诚美矣，师道可无之。"]},{"t":"卢道子赴铨试","f":"五言律诗","c":["高才真干父，新渥继难兄。","舟楫维湘岸，簪缨觐汉京。","学虽工比兴，科亦要刑名。","书律三冬足，荣华一战成。"]},{"t":"古樟书堂","f":"五言律诗","c":["问讯书堂士，门前有古樟。","植根深入地，盘势阔连冈。","雾合琴书润，风来砚席凉。","试赓云下曲，馀韵绕琳琅。"]},{"t":"叶显甫生日","f":"七言律诗","c":["客里今年庆事新，星香三日两生辰。","已歌西母如椿寿，又赞东床似玉人。","卯观妙传仙祖诀，霞觞同汎我家春。","年年红紫芳菲月，不负功名富贵身。"]},{"t":"司马归州挽诗 其一","f":"五言律诗","c":["玉立气如春，魁然长者人。","三朝陈素业，两郡驾朱轮。","国干须名族，吾衰倚大姻。","那知沙步酒，一别遂终身。"]},{"t":"司马归州挽诗 其二","f":"五言律诗","c":["矻矻秭归山，长身困远官。","旧租无折变，新路有平宽。","报以孙将子，森然玉与兰。","自随梅福去，云外跨飞鸾。"]},{"t":"司马侍郎挽诗 其一","f":"五言律诗","c":["公之曾大父，昔者老先生。","日月扶丹扆，乾坤仗赤诚。","诒谋三世重，谨始一言清。","今日书生剉，临风作雨倾。"]},{"t":"司马侍郎挽诗 其二","f":"五言律诗","c":["生身何恨晚，犹识孝曾孙。","姓字惊乔木，仪型想九原。","百年馀父老，双泪落轺轩。","此意今谁领，凭高只断魂。"]},{"t":"四月二十八日轮对遇雨","f":"七言律诗","c":["攒梆叠鼓递相催，西府东班次第来。","雨入北门千步湿，天临后殿九重开。","尝时只在中廷拜，此日容穿左序回。","叨近威颜陈悃愊，愧无崇论补涓埃。"]},{"t":"四次韵李校书雪中临唐人阴符经","f":"七言律诗","c":["乘兴能临褚令书，无人知是戴公庐。","映窗寒雪天相借，嗜古高情我不如。","贞观风流沦没后，凌烟名字断残馀。","李侯用意青云外，肯与时人较疾徐。"]},{"t":"四伯父生日 其一","f":"七言律诗","c":["春入芳兰喜气浓，天风吹下庆重重。","大儿稳护梁州罽，小女登高监宅龙。","南亩新年付熊骥，北窗长日慕乔松。","阿咸多病宜偕隐，自洗山罍劝嗣宗。"]},{"t":"四伯父生朝三首 其三","f":"七言律诗","c":["农郊有喜万人知，三日甘霖绿野肥。","动地欢声连谷旦，降神喜颂入春围。","云充画栋排金鸭，花满前行立綵衣。","七十今年须预庆，明年群玉正天飞。"]},{"t":"四伯父生朝三首 其二","f":"七言律诗","c":["夜阑脩竹罢传觞，清晓诜诜辑燕堂。","浴冠舞童春服盛，秀眉齯齿颂声长。","博山细吐晴霏润，大斗高斟臈味香。","华发他年多胜事，凤纶重叠拜恩光。"]},{"t":"四伯父生朝三首 其一","f":"七言律诗","c":["花到酴醾芍药时，人如仙桂大椿诗。","一年春事莺初懒，千岁光阴鹤未迟。","鬓雪多于南极老，脸朱浓似舞雩儿。","醺醺曲水馀酲在，又酌流霞劝寿卮。"]},{"t":"四雪诗用前韵寓四字 其二","f":"五言律诗","c":["气用乾阳壮，云兴初望神。","渎流连夜剪，泽草万花新。","暮夜翻疑晓，冬郊总是春。","皇皇天一色，穆穆径无人。"]},{"t":"四雪诗用前韵寓四字 其一","f":"五言律诗","c":["皓景连辛甲，寒歌遍仄平。","会同符盛治，假合类浮生。","境变西山色，诗翻郢曲新。","且随车角住，休趁马蹄行。"]},{"t":"处州叶德共挽诗 其二","f":"五言律诗","c":["儒服能军事，人心以富行。","邑中无恶少，堂上有佳名。","死得安仁诔，生经短簿评。","哀荣有如此，何必汉公卿。"]},{"t":"处州叶德共挽诗 其一","f":"五言律诗","c":["属厌多年所，归来近月评。","望之重十舍，已矣又平生。","无复论乡曲，犹能接舅甥。","短章随嘒管，凄断不成声。"]},{"t":"失题","f":"七言律诗","c":["肇开苕霅葬斯文，从此新安族望分。","牴角烟寒山烈烈，梅溪风切水沄沄。","何人可志林宗墓，他日应寻董相坟。","桃李无言蹊自远，五湖清泪湿春云。"]},{"t":"头颅四十有感","f":"七言律诗","c":["学古光阴惜寸分，济时心胆慕华勋。","少年有意不称意，暮景欲云何所云。","行矣未能真不惑，归与长恐遂无闻。","朝来不敢看清镜，怕有轻霜下碧云。"]},{"t":"对月","f":"五言律诗","c":["少日曾相识，重来有故情。","殷勤前度月，依旧向人明。","扰扰魄生死，区区轮满盈。","何如长半掩，万古不西倾。"]},{"t":"对雪呈判府周丞相","f":"七言律诗","c":["燮调曾转九重天，偃息何难十国连。","坐遣朝云将朔雪，一清瘴雨与蛮烟。","丰年预见宽心曲，俭俗能忘念目前。","更想朝来穷巷里，闭门高卧有遗贤。"]},{"t":"归自寸金堤绕城南转至望涉楼下柳阴扶路草色际天春意融怡不可名状","f":"七言律诗","c":["十里河堤接郡城，城边杨柳密于屏。","行人尽日翠阴里，啼鸟数声残酒醒。","七泽观前无限草，高沙湖外一时青。","斜阳极目春如海，只有平庵两鬓星。"]},{"t":"母氏立春日庆七十","f":"七言律诗","c":["土牛门外打春鞭，綵凤堂前庆寿笺。","西母东公俱得岁，古稀今有见双全。","群仙别演长生籍，大历重开甲子年。","更值圜坛鸡赦出，两封花诰一般鲜。"]},{"t":"用舍弟韵送妹婿郑子仁湖南漕试","f":"七言律诗","c":["笔力追风内厩黄，词源下峡九秋艎。","经行帝子云璈地，祓饰骚人月璐章。","亲老一生儿共婿，吾衰七见暑成凉。","门阑正倚乘龙重，快踏层云觐九阳。"]},{"t":"用韵为十六弟寿","f":"五言律诗","c":["南极星中老，朱陵洞里仙。","相呼乘大夏，抱出送高贤。","八荚蓂垂地，初弦桂拂天。","它时南宛路，此日正开筵。"]},{"t":"用韵寿郑子仁二首 其二","f":"七言律诗","c":["殿阁风来六荚新，勾芒犹是管馀春。","明朝斗外星初转，今日樽前夏未真。","九十日都成此会，八千年更属何人。","并将骀荡清和德，钟作崧高骏极神。"]},{"t":"用韵寿郑子仁二首 其一","f":"七言律诗","c":["千载吾家得郑君，至今情义蔼于春。","向人心事缁衣武，伴我躬耕谷口真。","父老尚谈宣幕事，世科元是探花人。","朱庭玉色浑相似，曾向冰绡识寿神。"]},{"t":"用韵送任以道入四川总领幕府二首 其二","f":"七言律诗","c":["软红尘里不争新，蠹简香中却竞辰。","邺架孔堂深贮腹，鲍篇陈檄妙看亲。","刍粮轧轧虚旁午，岁月悠悠老秩寅。","曷日阴山行汉马，大挥椽笔布王春。"]},{"t":"用韵送任以道入四川总领幕府二首 其一","f":"七言律诗","c":["铜梁天汉一轺新，红芰清波去及辰。","顾我索居谁为友，与君难别岂关亲。","飞书上陇催庚癸，闭息匡床候子寅。","出处虽殊心事一，濂溪风月舞雩春。"]},{"t":"用韵送倪教授千里","f":"七言律诗","c":["吟罢随州路口诗，先生书剑此东之。","边城它日无斯士，病叟中年惜所知。","出处如今方永隔，逢迎何处是前期。","故人若问孙文宝，闭户焚香读坎离。"]},{"t":"白莲","f":"七言律诗","c":["似云如月画图难，似立如行意象宽。","太华峰头天欲晓，魏王池上日初残。","超超韵出千花外，浩浩香来六月寒。","正用一夔当大夏，可须浮艳满春阑。"]},{"t":"石塘","f":"五言律诗","c":["市夹河漘好，桥当浦口雄。","湿云低障日，斜雨急收风。","石岸蜿蜒去，松江杳霭中。","知几吾晚矣，惭汗过垂虹。"]},{"t":"立春前一日书事","f":"七言律诗","c":["明日天车始建寅，今朝犹是去年人。","江城半夜传黄纸，嘉定新书下紫宸。","山雪多情来送腊，湖波著色去迎春。","旋烘寒饼缠生菜，想见家贫忆路贫。"]},{"t":"次韵赵佥判苦雨","f":"七言律诗","c":["多谢新诗起钝顽，扣门佳梦忽惊残。","句中解貌秋霖苦，读罢犹闻夜滴寒。","谁道贵游无世话，君今清尚更儒酸。","向来白贺风流在，勉立修名后代看。"]},{"t":"任安抚挽诗 其一","f":"五言律诗","c":["已矣天难问，哀哉道竟孤。","风流前辈似，胆略世人无。","缓急谋谟见，寻常尺寸拘。","明时非不用，志士自多迂。"]},{"t":"任安抚挽诗 其二","f":"五言律诗","c":["新息任夫子，东坡所父师。","只馀盘叟在，犹乃故家时。","閒抚伊吾剑，吟成绿野诗。","中原遗老尽，旧事有谁知。"]},{"t":"任安道生日 其二","f":"七言律诗","c":["豪风横雨洗新春，掣电惊雷起蛰鳞。","七百里开云土润，八千年庆大椿辰。","太牢醇酎春台上，金马公车要路亲。","凛凛河图门户在，稳将才业嗣前人。"]},{"t":"任安道生日 其一","f":"七言律诗","c":["桐川酒正夏王孙，四百遐龄旧德存。","解与狄仪传酿法，不妨吾祖自昌言。","三分历草初除一，百万春花欲化浑。","夺得年头作生日，尽收芳气入芳樽。"]},{"t":"任安道生日 其三","f":"七言律诗","c":["九分才是一分春，从此看春更七旬。","行世功名初发脚，出门富贵即随身。","棋逢要路方高著，马得亨衢定轶尘。","伏枥自怜吾久矣，傍观甘作烂柯人。"]},{"t":"任至道招饮香海棠下","f":"七言律诗","c":["眼见名花病已轻，手攀芳树思如酲。","飘零万片都无恨，点缀残枝更有情。","日暮莫辞银烛照，夜寒谁为宝瓶生。","饮阑可怕留连久，满地香红忍得行。"]},{"t":"任咏道生日","f":"七言律诗","c":["月当天上连山易，日占人间闰路棋。","华岳金精供爽气，广寒银阙献高枝。","鳏鱼渴凤尘缘净，寿鹤灵龟内景迟。","好把文章收富贵，却将功行享耆颐。"]},{"t":"任□□生日","f":"七言律诗","c":["盘堆郁薁粲豳风，钟汎函林拂嶰筒。","一朵杖华千里到，六双蓂荚五云中。","初庚恰向今晨足，鼎甲悬知后日崇。","新息陂头多赤雁，看排行序上层空。"]},{"t":"休日值晴张园观梅同舍不期而集","f":"七言律诗","c":["玉照堂前富贵梅，倚春骄腊未轻开。","费他一月春风了，催得五分花意回。","恰是佳晴难放过，偶然胜士得追陪。","君看好景天还吝，一夜轻云带雨来。"]},{"t":"会葬外舅还过李万州墓下","f":"七言律诗","c":["又送人间一古今，两翁相望接云岑。","屈伸固是乾坤用，恻怆岂非天地心。","野迥茆风声索索，山深松日影阴阴。","平生来往风流在，应有幽人见苦吟。"]},{"t":"再用丝字韵谢张留守垂访新居","f":"七言律诗","c":["画出城都客子诗，元戎真赴野人期。","白沙翠竹新晴罢，红旆青油小队移。","圣世散材甘永弃，师门曲木未全遗。","惊魄已作逃弦雁，只愿长江理钓丝。"]},{"t":"再次前韵唁南湖放莺燕","f":"七言律诗","c":["谁向南湖赋白头，西风团扇有新愁。","归巢海燕无多日，出谷暖莺何处游。","文杏梁边泥尚湿，绿杨堤畔水长流。","有情莫扫园中路，舞影歌尘处处留。"]},{"t":"再次前韵留黄县尉二首 其二","f":"七言律诗","c":["天教槐辅抚藩州，人道梅仙百不愁。","倚阁才情翻作苦，留连诗卷不成酬。","我方设棘蒐芹水，渠自张蒲去荻洲。","二十四泷高浪里，卧敲船板醉吟休。"]},{"t":"再次前韵留黄县尉二首 其一","f":"七言律诗","c":["邮亭别酒也须倾，底作匆匆向永明。","莲里青心犹有薏，雨中红日可无情。","吾伊未了吾难出，子墨传言子试评。","回首便成千里恨，论心何惜片时程。"]},{"t":"再次前韵答高秀才言诗","f":"七言律诗","c":["万仞峥嵘赤手攀，但能进步莫忧竿。","一生便作苦吟去，万事何如得句欢。","鼓气易衰怜我退，市声方午似君难。","丈夫不用分畦畛，臭味从今蕙与兰。"]},{"t":"再次前韵督周子问雪中以疾辞诗","f":"五言律诗","c":["散花侵示疾，造物戏公深。","毳饭添三白，熊经试一禽。","从来诗愈疟，枉去药关心。","无限山阴兴，匡床好越吟。"]},{"t":"再次韵赵佥判投赠","f":"七言律诗","c":["天街何日雨云乾，梦想王孙白玉颜。","一日能从晦岩子，十年不负会稽山。","吟诗可但师唐白，服礼终期类汉间。","万事总当如荫户，己私除尽即心闲。"]},{"t":"再次韵谢张直阁惠雪诗","f":"七言律诗","c":["案头拥被映残书，溪上何人访敝庐。","凤沼诗仙王二十，兔园赋客马相如。","玉龙百万推敲里，月界三千锻鍊馀。","合侍金舆和黄竹，一官何事尚徐徐。"]},{"t":"再次韵谢潘都干","f":"七言律诗","c":["壮士从军不废诗，何妨笳鼓间箫篪。","秋城夜观无公事，月胁天心有咏思。","岁稔公私方暇乐，时平福履正来绥。","金陵风月三千首，共看君侯羽扇麾。"]},{"t":"再次韵赠潘杨二君二首 其二","f":"七言律诗","c":["杨子高才作小诗，似裁推管制纤篪。","乱流不怕公无渡，绝险宁愁我所思。","百镒黄金装马首，五文绣段系车绥。","横行海内无坚阵，目短曹刘不足麾。"]},{"t":"再次韵赠潘杨二君二首 其一","f":"七言律诗","c":["今代潘郎老作诗，友声相应速如篪。","燃萁短句宁论步，联鼎长吟不待思。","武事解歌三箭定，文容堪颂万邦绥。","从公更觅中和什，惭愧无因把蜀麾。"]},{"t":"再到东坡","f":"七言律诗","c":["江山不用借花辉，满坂黄泥落叶稀。","四海共知坡下路，昔人犹想梦中归。","小桥暗井千年话，秋菊寒泉一缕霏。","恐被先生浮大白，尊前休说是和非。"]},{"t":"再和病起韵答曹仲明","f":"七言律诗","c":["爱我空城美疢休，未蒙针砭若为瘳。","齿疏发脱真无用，语涩行迟见寡尤。","稍善知医似高子，敢云称病学留侯。","径烦曹植波澜句，一为元微破隐忧。"]},{"t":"再送陈沅江","f":"七言律诗","c":["三年食茆厌冰厅，一日栽桃绕带城。","水入洞庭天正阔，山连黔徼地偏清。","醉歌屈子醒时赋，琴和湘娥瑟外声。","若到江滨逢九肋，为言稀有是轻生。"]},{"t":"再送黄醇甫四川制干二首 其二","f":"七言律诗","c":["柏氏诸龙我独蛇，乐翁群玉子无瑕。","高曾未远情终在，闽楚相望迹自赊。","晓镜雪侵莲府绿，夜堂风入绛帷纱。","天将广厦包全蜀，李监门阑喜可涯。"]},{"t":"再送黄醇甫四川制干二首 其一","f":"七言律诗","c":["未冠声名璧水流，已嗔袍笏壮龄收。","更堪绿鬓劳乌绶，好去青天上碧油。","百岁重亲谁得似，十年三策未经酬。","归来展尽平生话，莫负东阳沈隐侯。"]},{"t":"再得崇道观寄王左史","f":"七言律诗","c":["药鼎无时手自煎，万囊长在枕头边。","罪今脱矣从头白，病已安之用涕涟。","始悟旧诗成卦影，只消崇道了天年。","故人读罢知余喜，遥举真珠百斛泉。"]},{"t":"刘寺置酒遇雨次韵答王大著","f":"七言律诗","c":["胜绝今年第一筹，钱湖刘寺雨中游。","汤倾衢点云随肘，羹汎戎酥雪满瓯。","竹坞张烟围客住，梅檐翻水劝人留。","只因元气淋漓手，计会天公作此谋。"]},{"t":"刘都翰送伊川山谷二像","f":"七言律诗","c":["十年道学诚明处，四海诗篇雅颂馀。","元祐向来基宥密，涪江相逐伴樵渔。","坐中苍白谁安立，身后丹青独久如。","再拜两公何所见，衣巾端肯过吾庐。"]},{"t":"同叶卿至龙井二首 其二","f":"五言律诗","c":["半世闻龙井，今年傍驿车。","山中无乳窦，世上有鸣渠。","投石占阴洞，班荆饭野蔬。","京尘红一丈，无路到僧居。"]},{"t":"同叶卿至龙井二首 其一","f":"五言律诗","c":["送客得兹游，湖边上小舟。","水吞沙岸远，云绽日光浮。","地转风篁密，山藏野寺幽。","飞泉如有意，夹路奏鸣球。"]},{"t":"同刘监丞步观长干寺后诸园","f":"七言律诗","c":["游人塞道不容车，千古金陵少妇居。","朱雀大桁春雨后，乌衣深巷晓风初。","红红白白花无数，下下高高意有馀。","此景只应闲客管，瘿黎轻盖日徐徐。"]},{"t":"同舍置酒孙园招熊莘老","f":"七言律诗","c":["千年故国阳春地，今日王孙尚姓熊。","坐上堂堂皆此客，云间衮衮看诸公。","题诗小苑春风里，把酒夕阳烟雨中。","莫恨来迟桃李过，绿襕衫色正葱葱。"]},{"t":"圩田","f":"七言律诗","c":["港里高圩圩内田，露苗风影碧芊芊。","家家绕屋栽杨柳，处处通渠种芰莲。","老去何年真有此，客中半世尚茫然。","自怜赤日黄流里，又买扬州上水船。"]},{"t":"夹得胡仲芳诗次韵","f":"七言律诗","c":["天遣清明作小寒，人从赤壁上青山。","颇宜书更形骸外，赖有诗犹意气间。","一日水程无几住，百篇火急莫令悭。","杖藜径入渔樵去，从此因君得往还。"]},{"t":"守岁 其二","f":"七言律诗","c":["大家投辖驻年先，共判今宵一醉长。","不管栖禽惊列炬，且倾浮蚁尽馀觞。","茶馗已作当关面，花柳谁知惜别肠。","看取平生双鬓发，也随新岁著新霜。"]},{"t":"守岁 其一","f":"七言律诗","c":["人情怜旧复怜新，扰扰通宵杂笑嚬。","炷蜡煎膏留漏箭，买椒沽酒办厨珍。","一声竹里千家晓，百和香中九陌春。","莫道病夫无节序，明朝清镜满梳银。"]},{"t":"成都二月十五日补试院呈同官","f":"七言律诗","c":["向来耆旧日争辉，太息西来万事非。","一笑烘堂吾岂敢，百年忧世泪仍挥。","洋洋大国风流在，奄奄诸生气息微。","欲挽岷江注东海，吾衰无力只思归。"]},{"t":"曲湘湾","f":"七言律诗","c":["两崖左右蜜房穿，一水中间蚁线旋。","蹙起浪涡知有石，荡开云影倒窥天。","当洪没没青螺暗，过漱霏霏白琲圆。","我欲濯缨渠濯足，一生输与钓鱼船。"]},{"t":"有感","f":"七言律诗","c":["几许心期百未偿，更将疏发对苍茫。","江声直上鲸波去，山色回看虎踞长。","乱后碧芜荒楚甸，云间孤塔见维扬。","承平旧事无人说，闲倚栏干送夕阳。"]},{"t":"次刘子野送别韵","f":"七言律诗","c":["贾谊莫思行说背，陈汤空想郅支头。","子规枝上三更觉，白鹭山前万事休。","櫜矢戢戈歌四夏，带牛佩犊免防秋。","一犁先向东郊去，稻滑蔬肥百不愁。"]},{"t":"次李校书韵嘲阁下红梅","f":"七言律诗","c":["托迹千花冀可曹，冰姿何敢露秋毫。","祗随婢子希红药，肯信仙家有碧桃。","照影日华烘玉颊，承恩衢勺醉香醪。","自抛臈雪茆檐梦，应羡春风画阁高。"]},{"t":"次罗机宜韵 其一","f":"五言律诗","c":["笃道罗夫子，平生一展禽。","由由无失己，耿耿独垂今。","问舍家仍在，居家隐自深。","祇今人不置，无处避朱金。"]},{"t":"次罗机宜韵 其二","f":"五言律诗","c":["不识田何易，空然愧项生。","学文经子厚，评品得钟嵘。","内省无他技，谁欺有隽声。","后来资汲引，因见古人情。"]},{"t":"次前韵招郑检法","f":"五言律诗","c":["人健萸真好，尊开菊自知。","无聊念前日，一笑及斯时。","高处云如帽，愁边雨欲丝。","能来纸窗底，相伴赋新诗。"]},{"t":"次前韵答徐监门","f":"七言律诗","c":["依环仿磬作园池，戛玉铿金出好词。","世擅文章从魏氏，家传仁义见韩碑。","抱关碌碌卑飞日，去国迟迟独往时。","相值两穷方有味，短笺朝暮送新诗。"]},{"t":"次前韵谢王主簿二首 其二","f":"七言律诗","c":["南州高士到湘州，山鬼湘娥暮暮愁。","行世头颅浑欲老，驾天胸次未经酬。","搜残风月三千界，吟破江湖九十洲。","谁报玉皇香案道，早将关放石渠休。"]},{"t":"次前韵谢王主簿二首 其一","f":"七言律诗","c":["夷甫风姿满坐倾，浚冲电目照人明。","更拈秋水长天句，来映清霜十月晴。","援笔而成祢处士，摇毫不尽崔廷评。","若容跛鳖追高步，勿恤驱尘小作程。"]},{"t":"次前韵督高秀才和诗","f":"五言律诗","c":["一雪来何暮，经年望已深。","狂于三月絮，清甚九皋禽。","纵未扁舟兴，能忘五字心。","如何高处士，断得此时吟。"]},{"t":"次曾宣干焕送别韵","f":"七言律诗","c":["戎事急于翻白饼，人情难似塞黄河。","谁能戴雪三千丈，更踏冲风十二波。","父老共倾同社酒，儿童齐唱牧牛歌。","烦君为较田家乐，比似兵家孰少多。"]},{"t":"次韵","f":"七言律诗","c":["高沙白魝记天如，葵扇桃笙度日居。","诗里燕虫时漫与，醉中鸥鸟正于胥。","忽遭唤起披金甲，自笑平生论石渠。","身世万端谁得料，一番江雨又成馀。"]},{"t":"次韵乡人华秀才冬至日投赠二首 其二","f":"七言律诗","c":["异乡初见子文章，短至仍逢日吉良。","下马入门知意重，芳华赠我愧情长。","笔端风味谁能及，江上形容莫自伤。","一线阳光真白璧，九衢春梦付黄粱。"]},{"t":"次韵乡人华秀才冬至日投赠二首 其一","f":"七言律诗","c":["深知道长属仁贤，甚爱阳来复旧毡。","凤历新灰浮缇室，牛星初度转青天。","五云嘉气书周典，七日灵文验孔编。","忽忽穷愁休怅恨，东风已到玉梅前。"]},{"t":"次韵乡人贺归","f":"七言律诗","c":["早知芳树不如归，底用青天接翅飞。","但了寝门安与否，更关城廓是和非。","预愁计日当还次，安得穷年只掩扉。","羡杀能诗西阁老，一庵依旧鬓毛稀。"]},{"t":"次韵为乐黔州内子寿","f":"七言律诗","c":["四牧车前翟茀施，六珈光里振榆挥。","侯宫燕喜千年寿，天诏鸾封咫尺威。","西阁雨晴山靡靡，东湖云澹水微微。","春风无限长生意，客子何妨缓缓归。"]},{"t":"次韵王大著大享宿斋","f":"七言律诗","c":["浅学胡然敢望回，英躔幸甚得追陪。","谈锋羡子雨无极，诗境愧予田尽莱。","丛桂晚香牵独梦，小梅春思恼清才。","丁宁阁老须勤赋，早晚西扉咏砌苔。"]},{"t":"次韵王少清见赠","f":"五言律诗","c":["王谢风流在，千年故不磨。","子孙奇俊甚，生长见闻多。","容易三千首，铿鍧十二和。","故家文物盛，寒士得同科。"]},{"t":"次韵王少清重阳","f":"七言律诗","c":["旋收积雨放秋阳，天亦慇勤慰酒肠。","篱下看花元自逸，公前露首固非狂。","芙渠幕底乡心动，竹叶杯中古意长。","每到佳时怀旧隐，羡君犹尔愧吾忘。"]},{"t":"次韵王少清寒食感旧","f":"五言律诗","c":["爱酒王郎子，愁来日日中。","都门空旧观，楚俗自乡风。","客里寒无奈，年时事不同。","新裁罗袖薄，还向宝台烘。"]},{"t":"次韵王主簿同考试","f":"七言律诗","c":["文阵枞枞剑戟丛，唤回习气老臧宫。","分明天上三题草，消尽人间一世雄。","圣处门庭开荡荡，春来风景乐融融。","何年一解隋唐梏，展放诸生阙里中。"]},{"t":"次韵王司理二首 其一","f":"七言律诗","c":["它乡异县歘相逢，岐国家声耸岱崧。","仕宦一生无去国，周旋四世不言功。","太平时节司文事，满世交游尽至公。","若把安荣观后进，百年未抵一年中。"]},{"t":"次韵王司理二首 其二","f":"七言律诗","c":["对敌何曾挫一毫，避人堪笑却成逃。","莫思蓬户飞三箭，且向椿闱带两髦。","年少枉随流水去，老来方悟入山高。","儿童已办新诗句，拟钉门符换旧桃。"]},{"t":"次韵王醇甫藏秃笔三首 其三","f":"七言律诗","c":["剡剡兰台缀不亭，翩翩鹦鹉健相陵。","少时锋颖先毛遂，晚岁头颅嗣祖能。","杜老壁间留扫马，符王宫里罢栖蝇。","莫欺贫士无檀施，时向文房度一僧。"]},{"t":"次韵王醇甫藏秃笔三首 其二","f":"七言律诗","c":["黑头期汝作东亭，短发愁予对杜陵。","髡者此时今守积，颖乎平日尔诚能。","屡题秀句文如凤，几注仙经细似蝇。","可是诗人偏爱惜，诗人双鬓渐成僧。"]},{"t":"次韵王醇甫藏秃笔三首 其一","f":"七言律诗","c":["鼻祖有功平水土，耳孙无宅寄邱陵。","蚤因蒙氏收微效，晚向秦皇谢不能。","逸少凭渠取舒雁，阿思为尔逐飞蝇。","王郎世契真如此，莫讶为儒却爱僧。"]},{"t":"次韵卢漕木芙蓉二首 其二","f":"七言律诗","c":["吹残池面旆中央，幻出台前艳粉光。","衣典欲催愁杜老，鬓霜难拒笑潘郎。","风来尚恐波生陆，暑退犹疑叶可觞。","拟种陶朱三百树，广文茅屋未应荒。"]},{"t":"次韵卢漕木芙蓉二首 其一","f":"七言律诗","c":["风波久厌水中央，初日精神入槛光。","木末端来就词客，墙头应是误行郎。","高花大叶宜图障，浅绿深红照豆觞。","壮观秋容惟有此，霜边倒尽雨边荒。"]},{"t":"次韵田将仕年八十八岁作诗自喜三首 其三","f":"七言律诗","c":["茅檐桑户落穷居，两眼犹能读细书。","自说此生聊尔耳，亦知馀事竟何如。","春云入眼元无迹，秋竹刳心久更虚。","天与精神自难老，会看千岁跨龙鱼。"]},{"t":"次韵田将仕年八十八岁作诗自喜三首 其二","f":"七言律诗","c":["铜驼陌上少年时，走马驱车远四畿。","又见伏符明汉道，曾伤小雅咏周微。","一生世路高和下，何恨人情瘠与肥。","老矣胸怀百无著，自梳朝夕鬓毛稀。"]},{"t":"次韵田将仕年八十八岁作诗自喜三首 其一","f":"七言律诗","c":["东坡来饭辩才师，元祐真人宥密时。","生长太平经战伐，浮沈薄宦寄喧卑。","五朝遗老今谁在，万事当时恨独知。","此世阅人如传舍，吾人安更用名为。"]},{"t":"次韵岁暮对雪书怀","f":"五言律诗","c":["问寝荆江上，留家湘水滨。","心关两处念，鬓改一年新。","屑玉逢天富，铺瑶盖地贫。","归来见三白，因得贺乡人。"]},{"t":"次韵朱通判寄示盘龙山观瀑诗","f":"七言律诗","c":["百尺山头下玉龙，吾人到此得参同。","河来积石昆崙顶，日出蓬莱碧海东。","直自阴阳随处有，强分泉火本来空。","君看击石还呵砚，燥湿先生一性中。"]},{"t":"次韵江陵王抚干送行","f":"七言律诗","c":["江西回首白云深，磊石山边问水程。","少日经行嗟老大，壮心零落笑平生。","官曹无计逃寒冷，书册惟堪记姓名。","悔不早师王处士，药炉琴轸自关情。"]},{"t":"次韵江陵张抚干送行二首 其二","f":"五言律诗","c":["萧萧青草岸，籊籊钓鱼竿。","此地规逃世，傍人误唤官。","夏凉眠麓寺，春晚戏雩坛。","却笑平生谬，崎岖自作难。"]},{"t":"次韵江陵张抚干送行二首 其一","f":"五言律诗","c":["戍瓜违首夏，行李傍中秋。","此意元衰懒，吾生足滞留。","竹枝看峡舞，月子听吴讴。","官况能多少，栖栖一世愁。"]},{"t":"次韵自咏 其一","f":"五言律诗","c":["生意断无几，死灰难复然。","世方尊腊腊，吾亦梦先边。","江水青无地，岩云白似天。","短蓑将鬓发，听唱谢郎船。"]},{"t":"次韵自咏 其二","f":"五言律诗","c":["杂剧只如此，古人谁不然。","渭南寻竹坞，杜曲买桑田。","石裂山衔羽，松明火带烟。","夜深随射虎，归路恐迷阡。"]},{"t":"次韵张以道对雨","f":"七言律诗","c":["西湖水足镜新磨，竺寺云深著色多。","双桨满城舟子唱，一犁无数老农歌。","冬温无计邀滕六，春旱愁人似石皤。","但得新年堪浸种，不嗔花事雨中过。"]},{"t":"次韵张以道苕溪","f":"七言律诗","c":["诸人鼎列更茵重，客子愁边或酒中。","云缟弁山溪正碧，画无名手句专功。","年华若看蚁旋磨，世话何难龟蜕筒。","明日一蓑苕霅去，与君相伴作渔翁。"]},{"t":"次韵张参议送行","f":"七言律诗","c":["君王菲食继唐虞，北望中原忆故墟。","嗟我怀人无惮远，参卿军事且烦渠。","急须把酒浇天口，早与归朝说地舆。","湖水小儒无籍在，十年犹佩兔园书。"]},{"t":"次韵张直阁水仙花二首 其二","f":"七言律诗","c":["贝阙珠宫日月长，青鸾白凤恣翱翔。","试烦钟子传琴操，莫向田郎问国香。","风里翠鬟慵整顿，月中幽恨自凄凉。","鸥波万顷情何限，未羡春花占洛阳。"]},{"t":"次韵张直阁水仙花二首 其一","f":"七言律诗","c":["买得名花共载归，春风满眼豫章诗。","银台挹月杯光潋，翠被临波袜影迟。","山鬼湘娥通系牒，梅兄矾弟绝藩篱。","我家正在江横处，一笑相看更莫疑。"]},{"t":"次韵张直阁对雨","f":"七言律诗","c":["九重城里作山园，隔尽红尘一世喧。","今雨未妨连昨日，春寒聊为破冬温。","客传条令来梅圃，僮报平安向竹村。","我在道山犹羡子，世间谁似隐君尊。"]},{"t":"次韵张直阁雪诗余亦有诗方遣送而未达","f":"七言律诗","c":["信口粗吟信手书，苍黄未到隐君庐。","伻来已有诗相逼，我亦谁令子亦如。","写出崩腾来浩荡，看成飞舞带纡馀。","老夫赖有儿时狯，因索先偿得少徐。"]},{"t":"次韵张部门","f":"七言律诗","c":["管领孤梅近小窗，推排茗椀当壶浆。","且然入局无公事，除却申台有印章。","饭已抄经临小楷，兴馀挥句落斜行。","不堪平日诗千首，刚被人求米万箱。"]},{"t":"次韵张部门湖上二首 其二","f":"七言律诗","c":["诗兴春来似水翻，更添孤艇入云间。","中心白阁苏堤路，两岸南屏西竺山。","一日晴明输子往，半年风雨被渠悭。","攲眠窈窕冲融里，月白烟青未忍还。"]},{"t":"次韵张部门湖上二首 其一","f":"七言律诗","c":["已作西湖烂漫游，北山兰若更深幽。","骅骝蹀躞青林下，舴艋夷犹古渡头。","花满杨坡桃不语，声喧阴壑水争投。","可怜不共林宗泛，只有新诗许载酬。"]},{"t":"次韵李士衡失解送公衍赴调二首 其二","f":"七言律诗","c":["向来翰墨付群儿，直把行藏待主知。","风引去帆声猎猎，手调焦尾意迟迟。","遥知夜宿吹藜处，恰是春深造榜时。","预恐阿婆愁见我，略须回马避旌麾。"]},{"t":"次韵李士衡失解送公衍赴调二首 其一","f":"七言律诗","c":["世事从来亦偶然，何妨浊酒且中贤。","诸天入定凭谁问，五色迷人自古传。","谢客堂中劳梦草，谪仙市上且开船。","飞鸣款作三年计，好在秋花晚更鲜。"]},{"t":"次韵李校书贺张部门除寺簿诗","f":"五言律诗","c":["酷爱陶元亮，生憎庾子山。","杯中今兀兀，镜里昔斑斑。","愿子飞腾速，容予浩荡閒。","他时江海上，莫遣尺书悭。"]},{"t":"次韵李著作送行二首 其二","f":"七言律诗","c":["秋来定有池阳雁，飞过蓬莱报子知。","天上旧游今似梦，觉来追忆始堪悲。","檐前日屋融融暖，阁下风廊细细吹。","最爱石渠明月夜，清霜飞下老梅枝。"]},{"t":"次韵李著作送行二首 其一","f":"七言律诗","c":["群居未信相从乐，要识相从是别离。","芸阁掩关当宿夜，江船吹火未眠时。","无人见雁同持酒，有客看猿自赋诗。","诗墨酒痕随处有，故人谁与寄将知。"]},{"t":"次韵沈告院问讯南湖","f":"五言律诗","c":["欲问南湖事，南湖事若何。","主人新鳸正，风物旧沤波。","绿发深深柳，娇钿细细荷。","槛虚宜斗鸭，船过莫惊鹅。"]},{"t":"次韵沈若院见赠","f":"七言律诗","c":["三载鸣弦宓不齐，姓名飞动玉宸知。","从来兰省丝纶署，梦入栀林草木诗。","我亦放言聊尔耳，君真施手事于斯。","为寮况是张公子，锦笔淋浪日对持。"]},{"t":"次韵苏主管忆庄器之贤良","f":"五言律诗","c":["娟秀从牙茁，声名奋角羁。","人愁万事早，谁料一官迟。","宪也虽非病，桑乎可使饥。","有穷难手援，无梦叹吾衰。"]},{"t":"次韵周子问咏雪","f":"七言律诗","c":["扫罢残冰又辱临，唤回前雪与争新。","禁持酒力难为圣，倚赖诗肠即有神。","朝气颠狂从自舞，夜声骚屑会相亲。","白蘋满眼长安梦，三月杨花覆锦茵。"]},{"t":"次韵和张安抚九日龙山赋","f":"七言律诗","c":["使君千骑踏清秋，乞与他年说胜游。","自有名山无此客，痛湔遗臭为吾州。","野人已毕三时务，老子聊宽一日愁。","犹有平生忧国意，不堪摇落对江流。"]},{"t":"次韵和胡仲方正月二十五日雪","f":"七言律诗","c":["减却濠沟厚却城，散如丝忽聚如京。","夜兼风势千江立，晓借林花万象荣。","恃我柴门高卧稳，敌君竹阁醉吟清。","长歌慷慨摇冰柱，至乐衔心未易名。"]},{"t":"次韵和谢江陵杨县丞投赠四首 其四","f":"七言律诗","c":["买臣五十贵何疑，衣锦怀章亦未迟。","苕霅有情依辇毂，簪缨无数足亲知。","只消笑向长安得，何用歌穿郢市为。","江汉沮漳吾老矣，药囊如栉气如丝。"]},{"t":"次韵和谢江陵杨县丞投赠四首 其三","f":"七言律诗","c":["与君齐宦五云东，与我齐生一岁中。","今日天涯须共笑，半生头鬓略相同。","观中香火无官守，庭下吟哦少事功。","未必苕溪闲似此，买船归去莫匆匆。"]},{"t":"次韵和谢江陵杨县丞投赠四首 其二","f":"七言律诗","c":["径苔铺翠叶堆黄，生怕人来便踏伤。","病久养成心性懒，闲多衍得岁年长。","己拚故我忘俱尽，忽话当年喜欲狂。","莲荡稻田相对起，镜湖南北好风光。"]},{"t":"次韵和谢江陵杨县丞投赠四首 其一","f":"七言律诗","c":["柴门密掩但如孙，白榻高悬偶似陈。","皮骨久将梅共瘦，鬓毛难与柳争新。","却思二十三年上，曾醉千岩万壑滨。","蘋月蓼风如昨日，尧天依旧满怀春。"]},{"t":"次韵承甫兄重阳","f":"七言律诗","c":["露入枫林叶未黄，风将花信到南阳。","一年好处咏九日，四海几人雕寸肠。","偶尔至今成故事，亦须随分系萸囊。","陶生孟祖当时意，可但区区为一觞。"]},{"t":"次韵范有交秀才投赠二首 其二","f":"七言律诗","c":["旴江范子亦奇哉，谒入寒厅眼为开。","少日论心弋阳老，新年行脚艮斋回。","君方赤手骑生马，我已冥心学死灰。","空复项斯门地在，个中无处觅诗才。"]},{"t":"次韵范有交秀才投赠二首 其一","f":"七言律诗","c":["头颅看即已如斯，狡狯何能尚昔时。","物自有情非我也，笔因随意偶书之。","不知风壑焉由籁，但见春林忽自枝。","老去诗名多减尽，咏沂门户欲容窥。"]},{"t":"次韵郑检法与张秘书论命","f":"五言律诗","c":["曹刘元易识，甘石况经云。","五物时为帝，三辰岁有君。","平生信严子，今日得扬云。","两手分忠孝，往承华与勋。"]},{"t":"次韵叙李提刑往临先正治所并所闻先正论桃源事二首 其二","f":"五言律诗","c":["今日天香去，当时昼梦然。","试烘千岁鼎，如见一川田。","润带仙坛石，芳连古柏烟。","静中观篆大，依约画秦阡。"]},{"t":"次韵叙李提刑往临先正治所并所闻先正论桃源事二首 其一","f":"五言律诗","c":["畴昔拜臞仙，桃源问果然。","洞非人世外，花在此心边。","寂寂蒸霞地，沉沉浴日天。","南阳刘子骥，独泛问津船。"]},{"t":"次韵贺叶运干改官","f":"七言律诗","c":["伊人匪□即东如，于我谁何伴退居。","才到九门催引见，速来平地学追胥。","雷轰古县栽秾李，水满芳塘汎碧渠。","戏把闲忙问同异，莞然微笑刃之馀。"]},{"t":"次韵赵佥判投赠","f":"七言律诗","c":["三复新篇吻为乾，载赓馀韵甲生颜。","今无愈湜陪长吉，古有严徐伴小山。","秀出猗兰仙李外，思留春草桂枝閒。","从来只有诗人苦，可笑王孙不自闲。"]},{"t":"次韵送刘左史去国","f":"七言律诗","c":["手把东溪处士书，攲眠湖上小僧庐。","生憎人作侍臣看，自喜身今客子如。","去国祗堪千古重，看囊那得一钱馀。","二年两过刘郎洑，应为家林又少除。"]},{"t":"次韵送应秀才往池舒二州","f":"五言律诗","c":["瑶琴弹古曲，何事有哀音。","客子道途远，棘人霜露深。","齐山同雁宿，天柱共猿吟。","二牧高人问，归来满孝心。"]},{"t":"次韵送新潜江滕令 其二","f":"七言律诗","c":["县南堤破户全逃，县北堤存尚可苗。","春野纵耕无吠犬，秋场一笑足迎猫。","解牛巨手烹鬵水，戏彩深情化哺枭。","时唤云洲论小篆，少于韩蔡老于潮。"]},{"t":"次韵送新潜江滕令 其一","f":"七言律诗","c":["髯滕笔力万钧强，少日诗声远擅场。","身著青衫头半白，腰悬铜印绶仍黄。","鱼来俞市鲜无数，酒满龙渊乐讵央。","若许为氓仁政里，一廛烟水受渔郎。"]},{"t":"次韵重阳值雨","f":"七言律诗","c":["莫向西风怨雨寒，登高元自不须乾。","葛巾漉酒何妨湿，破帽沾泥亦足欢。","唤醉自应泉洒面，养花兼得露盈盘。","游人几许重阳恨，凭仗新诗一笑宽。"]},{"t":"次韵陶节推问疾","f":"七言律诗","c":["酒病诗狂失已多，之人未弃肯来过。","悔将虫篆疲锼刻，旋讲熊经学按摩。","容我力湔卢骆体，与君同赴闵颜科。","瑶琴一曲春风里，思绕龙门看洛河。"]},{"t":"次韵高秀才木芙蓉","f":"七言律诗","c":["流落秋江世未知，知心未有子西诗。","苏韩句外新相识，孔孟门中许独窥。","不怨碧桃真义命，最宜青女好襟期。","娉婷耻向东风嫁，羞杀邯郸道上姬。"]},{"t":"次韵高秀才重九二首 其一","f":"七言律诗","c":["未待经霜拆嫩黄，已思斜日醉高阳。","鬓毛拟共冠巾约，诗句先含萸菊香。","小雨微云愁令节，批风借月倚新章。","应门莫报催租吏，酒债如今也未偿。"]},{"t":"次韵高秀才重九二首 其二","f":"七言律诗","c":["茱萸未插鬓先黄，兄弟西陵更岳阳。","鸿雁来时俱是泪，菊花知汝为谁香。","台因抱病难重上，诗为催租已断章。","新样小槽官酿熟，输君直把九秋偿。"]},{"t":"次韵寄谢杨制机","f":"七言律诗","c":["把卷怆然不自胜，古来离合岂人能。","未应鬻剃尤穷发，暂喜餐蔬得枕肱。","身逐南云亲色养，梦寻巴瘴隔心朋。","囊中贝母烦分惠，独学仍愁旧病增。"]},{"t":"次韵黄县尉祁阳遇全州试官同归","f":"七言律诗","c":["粉字朱牌簇县津，绿蓑青笠洗行尘。","一时客路同归棹，半是年家及里人。","秦代徵君岩上石，吴时霸主涧中神。","休将短发供离恨，早卜宽乡作酒邻。"]},{"t":"次韵储检法帷字","f":"五言律诗","c":["岁月客中老，交游天下奇。","衰州访人物，台法妙天姿。","年事真堪惜，人情莫浪随。","青春能几许，绿叶看成帷。"]},{"t":"次韵曾宣干","f":"七言律诗","c":["无钵无箪晓自斋，一銎一衲晚逾乖。","战场实事膏兼血，广坐虚谈冢共骸。","虏事方然人尚尔，世途何者我犹谐。","道林自有山花鸟，收起棚前傀儡牌。"]},{"t":"次韵程尧仲风雨诗 其二","f":"七言律诗","c":["浩浩阴风彻屋号，霏霏寒雨一天毛。","撼醒花柳经年眼，润透郊原百尺膏。","鼓舞孰知神物妙，沾濡方表化工劳。","游人只见春能好，香满园林绿满壕。"]},{"t":"次韵程尧仲风雨诗 其一","f":"七言律诗","c":["春来长是雨相禁，春事能消几日阴。","一夜小桃红削迹，明朝芳草绿惊心。","墙沟㶁㶁忙如箭，檐瓦潇潇怨似吟。","前日东亭看花处，不知尊在与沙沈。"]},{"t":"次韵答任贡父见寄三首 其三","f":"五言律诗","c":["日者人间世，家传洛下书。","谁能定真实，转觉堕空虚。","莫倚文无害，常怀行有馀。","词华非所欠，水溢自成渠。"]},{"t":"次韵答任贡父见寄三首 其二","f":"五言律诗","c":["有情方是物，无敬莫言诚。","此事非俄测，由来只自成。","个中勤积累，熟处会分明。","未厌拘挛隘，他时满八瀛。"]},{"t":"次韵答任贡父见寄三首 其一","f":"五言律诗","c":["千金悬虿尾，一柱兀波心。","吾道今如此，微生力未禁。","正须公等助，莫废别来吟。","拄杖当分付，相期化邓林。"]},{"t":"次韵答刘正将","f":"七言律诗","c":["落魄刘郎住藕池，湖南湖北竹枝词。","风流故有诸孙句，绝妙都如幼妇碑。","玉斗歌成微醉后，银河曲就浅寒时。","文章自倚兼馀体，不分人来只看诗。"]},{"t":"次韵答吴阜之投赠","f":"七言律诗","c":["沈沈寒甃绠千寻，澹澹疏弦瑟五音。","读罢自今三太息，个中应有一生心。","君真骨相超凡马，我已情怀学展禽。","肯为明时当许事，科场文字未须深。"]},{"t":"次韵答罗鄂州二首 其二","f":"五言律诗","c":["任重心长在，年侵力未堪。","圣贤憎独学，老宿幸同参。","已信乾坤蕴，无踰孔孟谈。","谁能中道废，长使一生惭。"]},{"t":"次韵答罗鄂州二首 其一","f":"五言律诗","c":["相望才信宿，一出尚徘徊。","谁谓坚高处，真成竭蹶来。","人情伤蹭蹬，学力讳迟回。","欲火焚林去，如何水一杯。"]},{"t":"次韵答胡季履复荆门故宅","f":"七言律诗","c":["镜里枯疏雪点毛，笔端凌乱雨浮膏。","侵疆稍稍龟阴复，作堵渠渠鸿雁劳。","乔木有孙关国体，故基能筑是人豪。","自言书就堪□□，谁谓先公论太高。"]},{"t":"次韵答蜀人薛仲章","f":"七言律诗","c":["只怜久病刘公干，不羡多驺邓仲华。","解寄长年新句法，颇思前夜好灯花。","自离窗外千秋雪，长看天西一色霞。","想见疏桐凉月下，幽鸿无伴立寒沙。"]},{"t":"次韵谢处州乡人二首 其二","f":"七言律诗","c":["黄花和露作深秋，志士临风惜壮猷。","靡靡道途空接淅，摇摇心事剧悬旒。","儿时种木今盈抱，老去还家莫漫游。","侧耳乡书上霄汉，圣朝宾贡似成周。"]},{"t":"次韵谢处州乡人二首 其一","f":"七言律诗","c":["听说江湖万里身，十年流转狎波神。","乡心只羡秋鹰急，世味如何臈蚁醇。","耳识吴音疑故旧，眼看南士觉尖新。","袖中诗句清如许，何啻他乡见似人。"]},{"t":"次韵谢临川梁知县寄诗","f":"五言律诗","c":["友散萍分浪，师亡木拱阡。","年深多弃井，道远欠加鞭。","不寐思同社，何时共一廛。","瑟琴希旧曲，云淡觅前川。"]},{"t":"次韵新泸南张安抚送行","f":"七言律诗","c":["沧湖居士楚江皋，劝我嘉州竹叶醪。","侍立郎君清玉雪，赠行诗句妙风骚。","怀人眷眷辞多苦，接物卑卑道更高。","自听津亭三日语，扫除湖海一生豪。"]},{"t":"次韵路德章吴斗南同迓朱侍讲","f":"七言律诗","c":["两年京洛笔生埃，忽见清诗眼为开。","萧洒并将秋色写，雄豪更带夜潮来。","可怜拄腹五千卷，谁与浇愁三百杯。","莫遗晦翁闻世事，怕教兴尽却思回。"]},{"t":"次韵酬查仲文春日宴集","f":"七言律诗","c":["步屧随春亦偶来，堂前双燕莫深猜。","明年我自沧浪去，无限人从紫陌回。","宝扇临风听曲度，绣帘低日看花开。","一尊幸许陪诸老，急拍深杯未用催。"]},{"t":"次韵潘都干水晶菊二首 其二","f":"七言律诗","c":["莫遣秋霞到晚园，怕将铅脸照成丹。","落英但可和冰嚼，□色惟宜带月看。","清似雪霜仍耐久，老于篱落不言寒。","一枝合是闲人插，四海知侬鬓已潘。"]},{"t":"次韵潘都干水晶菊二首 其一","f":"七言律诗","c":["幕中安得野人园，种此晶荧白玉丹。","冷淡虽无九春分，风流还得一冬看。","银杯共色深宜酒，纸帐围香未怕寒。","只向河阳种桃李，今时潘胜旧时潘。"]},{"t":"次韵赠东湖周子问","f":"七言律诗","c":["玉锁凌空不可攀，卧听车马日三竿。","以湖拜命官名散，把酒封君国号欢。","父祖诗家三世将，弟兄文阵两秦难。","年丰母健无馀事，长作人间谢客兰。"]},{"t":"次韵赠刘正将","f":"五言律诗","c":["读子风林集，怀吾里塾时。","道途今老大，人事几推移。","宫省知名久，君王识面迟。","柳亭寒气入，谁赏玉台诗。"]},{"t":"江月亭会饮次袁主管韵恼吴钤辖","f":"七言律诗","c":["日西移幕看澄江，夜久回屏护烛光。","暗里微明认渔火，醉中时醒为荷香。","狂翻鹦鹉杯心绿，怒索蒲萄架底凉。","苦恨重云隔明月，嫦娥更在月中央。"]},{"t":"江陵送赵知县二首 其二","f":"七言律诗","c":["别离底处最堪怜，君上吴船我蜀船。","从此相思真万里，重来何止又三年。","司州刺史髭如戟，国子先生瘦似椽。","二子有情须问讯，为言重九向西川。"]},{"t":"江陵送赵知县二首 其一","f":"七言律诗","c":["万壑千岩相送时，灵星小雪上丰颐。","南云北梦重分首，扑漉繁霜满瘦髭。","功业向来真自许，头颅今日遂如斯。","英雄老大无人识，足扣双舷只自知。"]},{"t":"江梅","f":"七言律诗","c":["千林憔悴独含春，笑倚黄昏未识颦。","红小粉疏烟幂幂，影低香远水粼粼。","从教雪路宁愁冷，遮莫茆檐可怕贫。","欲问横枝缘底瘦，似无如有最禁人。"]},{"t":"江梅蜡梅同赋","f":"七言律诗","c":["淡白轻黄著绛跗，截肪蒸栗玉肌肤。","品题道骨谁高下，著莫清香似有无。","野服黄冠离世士，缟裙瑶佩列仙儒。","春风底处无红紫，谁肯冲寒到玉湖。"]},{"t":"约同行至浯溪作重九","f":"五言律诗","c":["九日明朝是，三浯自古高。","地能供此景，天亦念吾曹。","溪上风宜帽，山中菊可醪。","病夫虽不饮，短发却堪搔。"]},{"t":"老人命赋家庭双头牡丹","f":"七言律诗","c":["只与酴醾话独醒，不随桃李竞时名。","人怜国色无花对，天与风流并蒂生。","两两鹤红思并翥，双双鹿紫待齐鸣。","冲天食野方多庆，尽是仙翁手种成。"]},{"t":"自合州出陆所至例借宅宿食略无龃龉闻两川皆然至利夔路则龂龂不可矣","f":"五言律诗","c":["此土有善俗，江湖人未知。","过门随所谒，借宅总相宜。","阒静疑无主，餐眠遂及时。","客宾俱自爱，不敢坏藩篱。"]},{"t":"自过汉水菜花弥望不绝土人以其子为油","f":"七言律诗","c":["汉南汉北满平田，三月黄花也可怜。","惟有书生知此味，可无诗句到渠边。","油灯夜读书千卷，齑臼晨供饮十年。","今日相看总流落，洛阳樱笋正争先。"]},{"t":"自黄州赤壁抛过三江口危甚","f":"五言律诗","c":["直打矶头上，横抛江口开。","水将天共去，风与浪俱来。","人压船舷正，竿牵帆索回。","长年誇好手，不道客心灰。"]},{"t":"至斋诗为刘知录作","f":"七言律诗","c":["酒边琴外蕣华明，栗里幽人远念生。","一寸光阴知有限，百年心事恐无成。","追随春服攀高驾，指点雩童问去程。","篑土未升泉有达，高深那得便忘情。"]},{"t":"行香早起","f":"五言律诗","c":["露入襟裳冷，风传带舄清。","天街摇断梦，原庙听攒更。","阙角升云气，檐牙镂月明。","未教阳彩动，应怕路尘生。"]},{"t":"西坡","f":"七言律诗","c":["西坡仙去漪岚在，重到堂中廿二年。","依旧庐山当左阖，新添濠水注前川。","浑无障碍千峰处，长有澄鲜万顷天。","但得此心如此地，不妨朝暮与周旋。"]},{"t":"观澜阁","f":"七言律诗","c":["先生高阁水之滨，一秃翁从众主人。","欲说观澜先自愧，况逢收潦更难陈。","霜馀过濑声逾急，日落浮霞景转新。","千里迢迢春不断，陶潜曾点是知津。"]},{"t":"访东坡题高风堂屏间","f":"七言律诗","c":["樊口齐安一水间，少年行役鬓成班。","云开甲子三秋雨，日射淮南一带山。","战血浓时云梦远，受恩深处老身闲。","登临莫唱纶巾曲，栖鹘危巢再可攀。"]},{"t":"过上海寨昔人于此潴水以限北方","f":"七言律诗","c":["原田漫漫不知津，春寨清明思杀人。","雨后烧痕无润泽，烟中日色少精神。","郢城南地沟隍古，海寨东西径遂新。","谁见当时经画意，只今高浪化征尘。"]},{"t":"过如春堂观赵德麟诗帖因次赵成卿韵","f":"七言律诗","c":["阿麟文采近西京，付与而公翰墨名。","今日如春堂上看，当年遗帖子孙荣。","元丰曲里承平话，小杜诗中战伐情。","济上旧游成一梦，王孙端复可怜生。"]},{"t":"过阳罗洑","f":"七言律诗","c":["阳罗洑外黄陂路，滠口湖边孝感河。","钲鼓已通南草市，腥膻欲涴大江波。","家家户外无惊犬，日日辕门有凯歌。","端藉圣朝威德厚，亦烦诸将战功多。"]},{"t":"过秀寄麋秘书","f":"七言律诗","c":["圆峤仙人厌久如，戏求同颖作周书。","半生闻谊亲无路，一日同僚分有馀。","西子湖边春载酒，征官亭上夜分裾。","秋来怀抱知多少，总是归程细细摅。"]},{"t":"过故宜城 其一","f":"七言律诗","c":["跋马南城吊楚王，寂寥迁国岁年长。","故宫白道埋春草，小市青旗挂夕阳。","时有野鸡吞堕珥，更无遗像镇祠堂。","祗应平路桥边水，曾照当时后苑妆。"]},{"t":"严州建德道中","f":"七言律诗","c":["步步青山拥碧溪，村村麦陇入桑畦。","路将好景匆匆过，轿避柔柯故故低。","风饵雨纨香有思，带罗簪玉净无泥。","如今始悟严夫子，不把渔竿换介圭。"]},{"t":"伯父生朝","f":"七言律诗","c":["前宵谷雨放茶旗，昨日重三转酒池。","綵杖插花明兔碗，红牙调曲劝鸾卮。","煌煌朱脸烘华发，奕奕清睛耿秀眉。","南极寿星祗此是，不须高向画图窥。"]},{"t":"伯父新园","f":"七言律诗","c":["屋后回堤可当山，屋前沟港转清湾。","行人自笑高花外，倦客方吟积翠间。","曲折故应怜窈窕，崎岖未觉厌跻攀。","小桥直下前村路，百顷平园锦绣斑。"]},{"t":"佛图市","f":"五言律诗","c":["雨意阴连日，秋容淡满溪。","水穿平野断，云截远山低。","客路朝昏畏，村墟卯酉齐。","传闻近湖北，渐喜脱江西。"]},{"t":"别岳州","f":"七言律诗","c":["五更鼍鼓忽逢逢，舟子闻晴上北江。","推枕一兵辞画戟，开门三骑到篷窗。","鹿鸣厚意陈箱篚，伐木深情缀酒腔。","小雅风流千古在，飞吟亭下此心降。"]},{"t":"吴给事挽词 其二","f":"七言律诗","c":["少年胸次已吞秦，暮日肝肠独许陈。","正笏于今无此杰，垂车在昔有先民。","伤心岁晚逢诸老，屈指才难更几人。","寿乐哀荣公不恨，年来于此自酸辛。"]},{"t":"吴给事挽词 其一","f":"七言律诗","c":["我来镜水问遗民，想见堂堂报国身。","五月陂塘三百里，千年庙学一番新。","世传风烈今无数，自许经行得最亲。","一读金陵补天议，始知高处更惊人。"]},{"t":"呈罗机宜","f":"五言律诗","c":["抗己忧为的，咸腓惧丧躬。","自从夫子学，始见古人风。","有直终为讦，能和乃不同。","从今师下惠，一瓣敢忘公。"]},{"t":"宋帅移厨就市楼并饭胡黎州","f":"七言律诗","c":["天明喜气满沙头，小队行厨下楚楼。","太白稳归云阙去，德星聊向雪山游。","澹翁不为重溟怯，令子何辞九折愁。","荣杀上官穷观主，助公持酒记觥筹。"]},{"t":"寿王尚书二首 其二","f":"七言律诗","c":["去年曾赋泰山高，祇识君侯一味豪。","稍稍近能窥雾豹，堂堂元不挂秋毫。","直将空洞容君辈，从使参军似马曹。","此世此途荆棘久，借公馀勇为除薅。"]},{"t":"寿王尚书二首 其一","f":"七言律诗","c":["前年革履下星辰，那料如今更有春。","几为拜雩成俯膝，可辞持酒劳燋唇。","田家有喜新收麦，老子无何忽念莼。","欲去强留天意切，玉堂清夜出丝纶。"]},{"t":"寿母生朝","f":"七言律诗","c":["油河会散恰盈旬，春水痕生又浃辰。","堂上画图星欲动，夜来银烛火犹新。","江汀花草香风满，儿女孙曾乐事频。","海燕长随生日到，是渠三岛十洲人。"]},{"t":"寿邱安抚二首 其二","f":"七言律诗","c":["当年诏使再来时，物色依人喜可知。","萱麝半黄宜寿母，箨龙新绿见孙枝。","清香画戟沈沈处，永日薰风细细吹。","阁上南山青不尽，一杯相属寿无期。"]},{"t":"寿邱安抚二首 其一","f":"七言律诗","c":["湖上高荷五月凉，云间三五桂华香。","蒲葵影里民无暑，飞镜光中吏有霜。","日近天申才半浃，阳居大夏恰中央。","定扶真主开炎运，雪耻归来报上皇。"]},{"t":"张澧州挽诗 其二","f":"五言律诗","c":["坦然无一物，此意极寥寥。","生死东西魄，盈虚早晚潮。","何人清夜省，举世万波摇。","试把斯文诵，英魂或可招。"]},{"t":"张澧州挽诗 其一","f":"五言律诗","c":["持橐中朝贵，餐毡异域留。","人皆敬先德，我已识君侯。","气节传三世，才猷著两州。","承家五男子，身后更何求。"]},{"t":"张晋用晦自西和州来归","f":"七言律诗","c":["江海张公亦壮哉，雪蛆生处守边来。","绵裘六月冰如铁，土焙三更冷似灰。","栈踏曾云归蜀道，船欺急淖下瞿堆。","沙头病士眠初熟，又见征人万里回。"]},{"t":"张黎州挽诗","f":"五言律诗","c":["万里沈黎徼，民夷杂戍屯。","金钱宽两税，水泽润千门。","肃肃猩鼯静，潭潭壁垒尊。","远猷嗟未究，萧瑟定安原。"]},{"t":"抚州吴茂荣挽诗 其一","f":"五言律诗","c":["当年郡博士，致此一先生。","相见茂荣甫，似吾诸葛卿。","姓名书帝府，文行最乡评。","终老君何恨，伤时泪自倾。"]},{"t":"抚州吴茂荣挽诗 其二","f":"五言律诗","c":["世已尊科举，人多失老成。","行书周族党，身欠汉公卿。","犹藉千年润，能传万壑清。","怆怀非一士，何恨不知名。"]},{"t":"李校书轮对乞于故相家取上皇退位御笔上喜曰此万万年表照也","f":"七言律诗","c":["校书对罢天颜喜，再拜龙墀出殿来。","敕使传宣新宰相，驿书驰问旧元台。","上皇慈笔归中秘，学士忠名遍九垓。","榻畔祥风翻谏纸，朝衣收得异香回。"]},{"t":"李浦道中得家信","f":"五言律诗","c":["李浦江边路，星沉日未生。","逢人送家信，借火读天明。","上说儿曹健，中言客路晴。","促归仍劝缓，反覆见慈情。"]},{"t":"杨帅二首 其二","f":"七言律诗","c":["更须石叟共甘公，酌得民言帝自同。","四海人才容接里，百城生聚抚摩中。","似闻圣世开皇极，欲倚名贤镇士风。","看把璇玑扶大运，久于箕翼厚于嵩。"]},{"t":"杨帅二首 其一","f":"七言律诗","c":["谢天增霸复留恂，又到当时系韨辰。","宝带正看金芍药，玺书重傅玉麒麟。","上元新历开千岁，作噩祥名冠六辛。","恰用此年钟此杰，便乘嘉泰转洪钧。"]},{"t":"杨侍郎 其二","f":"七言律诗","c":["漕河水入汉江流，逆浪吹邻上比州。","为送新篇归岘首，亦知旧荫满沙头。","每思吾道长城在，常喜斯民命脉留。","圣宋卜年周十倍，须公同住八千秋。"]},{"t":"杨侍郎 其一","f":"七言律诗","c":["牙帐森森画戟红，心源澹澹玉壶空。","身如岘首羊太傅，意似鹿门庞德翁。","一贯精觕千虑到，两忘真赝万情融。","观公尚得今人爱，始觉东家道未穷。"]},{"t":"沥涧吴太皇庙","f":"五言律诗","c":["行间得子明，笑里下兹城。","好汉人难识，髯郎鉴独精。","溪巫荐村酒，舟子问江程。","颇忆濡须否，风幡作战声。"]},{"t":"社木湾","f":"七言律诗","c":["胡床却坐对澄江，一点无风镜面光。","帆过生绡多少幅，书成斜雁两三行。","白沙翠竹却却净，古岸新堤曲曲长。","唤作渔郎无一事，烟中艇子许匆忙。"]},{"t":"纱诗","f":"七言律诗","c":["芙蕖供色更供丝，缉就沙溪水面漪。","疏密整斜于雪似，香轻软细与风宜。","集裳妙得灵均意，织藕新翻蜀客词。","唤作似花还得否，只应花却似渠伊。"]},{"t":"谷山照僧能诗事母孝","f":"五言律诗","c":["照公诗甚清，月淡更云轻。","拂拂晴丝卷，霏霏柳絮萦。","我憎禅悖性，渠自孝钟情。","何似辞戎索，中原道上行。"]},{"t":"迓朱侍讲","f":"七言律诗","c":["欲就前贤去不如，几年功力在三馀。","终然觉我多金矿，幸甚逢翁侍玉除。","函丈中间亲觅诀，残编里许细观书。","自怜旧习如尘污，入发成胶未易梳。"]},{"t":"还过郢城","f":"七言律诗","c":["头白初行郢水边，故城千载尚依然。","岂无戍卒持钲鼓，应有居人沸管弦。","今日桑麻成沃野，几家茅竹散平川。","停车欲问当时事，红日翩翩下翠烟。"]},{"t":"还过渚宫 其二","f":"七言律诗","c":["下得腰舆倚瘦藜，闲将病骨照清陂。","三王故苑风流处，二月游人烂漫时。","此日鬓边应笑我，过来胸次却关谁。","一年两度西城去，独自宫园赋小诗。"]},{"t":"还过渚宫 其一","f":"七言律诗","c":["一兴一废古今同，熊绎当年起霸功。","沿汉溯江开国步，牧皋规偃建王宫。","重来旧日嬉游处，犹觉如今气象雄。","想见得臣并斗谷，治兵谋国震山东。"]},{"t":"还家即事","f":"七言律诗","c":["丁令归来故国时，乡人相见喜兼悲。","鬓毛憔悴精神在，邑里荒残府寺熙。","坐处不堪推老大，亲旁犹幸作婴儿。","莫言破虏前回事，得雨如今即是奇。"]},{"t":"进和御制闻喜宴诗","f":"七言律诗","c":["璧辉河綵绚宸章，鼎饪需云盛国光。","自昔祖宗崇礼遇，至今英俊入言扬。","明良旧咏回千古，槁饫新书侈万方。","神禹克艰心未已，更思忠节赞时康。"]},{"t":"阻风","f":"七言律诗","c":["阻风多日饭无羹，病酒中年睡不成。","扑面飞蚊来似鸭，闭船吹烛守如城。","良朋处处愁分袂，远客朝朝怕说兵。","石首山头逢一笑，白云相望雨新晴。"]},{"t":"阻北风简叶岳州","f":"七言律诗","c":["风颠下枪刺泥深，水长移船入港频。","帝子有情留客子，主人何幸得乡人。","星辰相纬周三卫，日月为常汉九宾。","公若赐环吾解缆，一般风色两家春。"]},{"t":"陈氏四芝图","f":"七言律诗","c":["当时一念继元昆，谁附飞章告九阍。","天听直无多远近，地灵顿有许便蕃。","拟笺此事呈诸老，盍引斯人侍至尊。","弭旱功夫消几许，草茅犹足动乾坤。"]},{"t":"陈宣干至赅","f":"七言律诗","c":["十年无事书生病，一日谈兵志士忙。","虏退便收前印绶，秋来仍著战衣裳。","天寒白兆腥风起，月黑黄陂燐火光。","试问蕲州陈大著，几多流血浸沙场。"]},{"t":"鸡冠后庭花同赋","f":"七言律诗","c":["长日鸡冠短后庭，倚风邪伫不胜情。","宋宗窗畔亲曾识，陈氏宫中旧得名。","尚想蹁跹啼晓意，犹疑宛转隔江声。","恓惶借与非常色，染出猩红特地明。"]},{"t":"叔父生日 其四","f":"七言律诗","c":["蓂花秃尽大椿生，月色昏时寿宿明。","眼见扶疏都变密，气钟和淑更能清。","弟兄相对谈前事，门户如今尽慰情。","除却偷闲无善颂，暮年多暇即为荣。"]},{"t":"叔父生日 其一","f":"七言律诗","c":["新年一百二十日，此酒年年须共斟。","竹岭松溪仙派远，龙山梦泽寿乡深。","戎葵百段缠头锦，卢橘千丸买酒金。","造物商量供酒费，怕教一事恼闲心。"]},{"t":"叔父生日 其三","f":"七言律诗","c":["一年生日最佳时，三老团栾总秀眉。","北榭空明新眼界，东床消息称心期。","竹林风景长宜酒，椒颂年华剩索诗。","试拂两弦听细摘，曲中元是閟宫词。"]},{"t":"叔父生日 其二","f":"七言律诗","c":["黄尘赤日万家团，中有金茎露一盘。","酒气薰天心独醒，市声摇屋鼻方鼾。","长生只用仁为药，至乐惟将静作欢。","嘉庆堂前齐指处，鬓毛如雪脸如丹。"]},{"t":"周子问作荞麦面冷淘二首 其二","f":"七言律诗","c":["调笑何郎莫漫嫌，一杯为洗太官膻。","品题今自东湖始，汤沐新封羹颉边。","短制牙筹防易断，半和麰粉借微坚。","山鸡隽永堪司荐，岂是从来野性便。"]},{"t":"周子问作荞麦面冷淘二首 其一","f":"七言律诗","c":["金鱼玉带相公孙，不受膏粱贵气吞。","忽唤寒儒共汤饼，翻疑晚饭过山村。","旧闻鹅鸭高飞尽，却恐神仙大药存。","一夜梦魂秋坂里，白花朱秆映柴门。"]},{"t":"和二十六日雪晴","f":"七言律诗","c":["雪中欢喜看瑶陵，雪后扶舆弄绮晴。","造物为人添眼界，病夫随处得心倾。","江南江北融融暖，春草春花日日生。","冻死穷檐吾不恨，欣欣同宇尽敷荣。"]},{"t":"和人谢送笔","f":"七言律诗","c":["词源浩浩笔渠渠，合珥华簪从属车。","洗眼看题挥月字，惊心犹似仰空书。","云林旧截双鸣管，霜野新蒐八窍居。","遣送文房惭瘦劣，千军挥扫正椽如。"]},{"t":"和王子一用韵告别","f":"七言律诗","c":["积吹摩空海有鲲，惊雷出地竹生孙。","娑罗木吐层层艳，窣堵波开面面阍。","小贴金花听疾足，淡书灰墨看高鶱。","街槐影里宫袍出，回首无忘汇泽门。"]},{"t":"和邓子及见贺韵","f":"七言律诗","c":["虚舟不记坎和流，槁木何心春共秋。","幸自一生甘辟谷，更须万户苦封留。","颇惩吾族骓千里，且学乡人橘满洲。","平生惟良资共理，病夫何以副旁求。"]},{"t":"和邓子及冬至谢送笔墨韵","f":"七言律诗","c":["年华添线又浮灰，忽忽穷愁不易裁。","惟有病人知客意，故冲寒雪送诗材。","昔誇三窟今成缚，少倚千寻老作煤。","妙用反从穷里得，一阳端自剥中来。"]},{"t":"和平江府倪教授送行","f":"七言律诗","c":["拜辞初下九天来，乞得斑衣学老莱。","六月火云烘去艇，三山风露隔飞埃。","多情送我诗盈轴，何意辞君酒一杯。","后夜相思江雨黑，短檠寒焰锦囊开。"]},{"t":"和刘子野见贺韵","f":"七言律诗","c":["汗青久别如山历，头白重分似斗城。","静著易林师子贡，共评诗品得钟嵘。","忽惊蒙水新衔宠，恍忆巴山旧印荣。","翠幕红灯莫相问，风流何似十年情。"]},{"t":"和宋帅出示所送李大著诗 其二","f":"七言律诗","c":["楼前人送四前旌，楼上诗添七字成。","蔽芾风中皆德意，黍苗雅里尽仁声。","请回南国条枚笔，归主中朝礼乐盟。","天下举安吾始乐，时哉王道正和平。"]},{"t":"和宋帅出示所送李大著诗 其三","f":"七言律诗","c":["病中三复舍人篇，可但才工与调妍。","心在雩坛沂水上，思通归鸟岫云边。","自将铁石为传授，不与风骚较袭沿。","听者座中谁最喜，丹邱道士舞如颠。"]},{"t":"和陈正己九日公安道中韵","f":"七言律诗","c":["何处山无九日花，故人相遇即为家。","君方去著风前帽，我已寒如露后葭。","久闭柴门陶岁月，晚凭儿子送生涯。","眼看一树堂堂去，双鬓那能不早华。"]},{"t":"和陈信民用韵以高抚州之命相招","f":"七言律诗","c":["入无锥瓦出无闾，笑杀康山老寄居。","客里光阴何以度，闲中亲旧顿然疏。","武冈文学来投卷，临汝君侯肯致书。","早晚一犁亲受地，时于笠底望行车。"]},{"t":"和陈待制江城毕工遇雪","f":"七言律诗","c":["鱼釜鹑衣救叔寒，牺樽羊饩度姑山。","瑞花一夜围青嶂，扶叶平明射白间。","遍雨麦田知地瘠，怕冰戍土谢天悭。","威棱迥出金汤外，十万边兵已北还。"]},{"t":"和胡抚干水仙花韵","f":"七言律诗","c":["瑶池蓬岛旧题名，岁晚江湖得此生。","水战风摇疑体弱，雪欺霜压见神清。","佩衿济济贤师友，兰玉诜诜好弟兄。","笞凤鞭鸾云泽畔，向人怀抱十分倾。"]},{"t":"和胡黎州贺得郡韵","f":"七言律诗","c":["波间来往愿莘其，林下归飞乐鸒斯。","罗致军门虽有礼，捉将官里便无诗。","齐瓜有日君方往，舜牧无人我亦咨。","西望雪山三百驿，何因杯酒得同持。"]},{"t":"和高抚州用韵相招","f":"七言律诗","c":["能使邦人保里闾，不能一日自安居。","废兴何敢于人怨，温饱从来作计疏。","旧景陆公新景贺，大题诗句小题庐。","慇慇唤我江西去，只用官船不用车。"]},{"t":"和彭世昌","f":"七言律诗","c":["有山有水胜吾闾，非旧非亲借屋居。","醉尉诃人何所恨，老彭于我未全疏。","右车牙少愁看栗，左目眵多怕读书。","比似渊明更穷绝，并无门巷与舟车。"]},{"t":"和揭尉见贺韵","f":"七言律诗","c":["茸茸弱线初迎复，轧轧阳机已转坤。","梅放小红明纸帐，竹分寒绿寿藤尊。","不愁故将逢陵尉，且喜仙官近市门。","还向陈年作新句，贺人今日拜春恩。"]},{"t":"和揭尉冬至韵","f":"五言律诗","c":["自古珍斯日，留机与世窥。","不因冬有至，谁识道之涯。","一点阳初动，千山木未知。","此时俄已复，端的更由谁。"]},{"t":"和韵答都昌胡令论诗","f":"七言律诗","c":["竹屋芦门映短墙，夜深宜月晓宜霜。","青山顾我如相识，白水粘天似故乡。","光景万端皆好句，肝肠百鍊见真刚。","今君正与民同乐，安得清愁满腹装。"]},{"t":"咏抛毬","f":"七言律诗","c":["綵旗丹柱倚春风，寒日清明罢绣工。","千仞骊珠翻锦带，五纹蛛网丽晴空。","百年日月跳丸里，一掷功名唾手中。","漠北将军贪蹋鞠，岂知兵法在吴宫。"]},{"t":"咏蜡梅","f":"七言律诗","c":["枯疏寒影变丰庞，的皪冰肌染沁黄。","难免世人栀蜡议，赖凭天骨蕙兰香。","情知不作和羹计，老去谁能弄粉妆。","却笑南枝心未死，寿阳新额小红裳。"]},{"t":"夜坐","f":"五言律诗","c":["天寒人倍爽，夜静雨初喧。","旧稿诗重定，新编手自翻。","相亲灯不厌，共坐意忘言。","独笑重城里，千家正梦魂。"]},{"t":"夜泛湘江","f":"五言律诗","c":["窈窈崖头黑，沉沉水面青。","枫林啸山鬼，竹月下湘灵。","欸乃元郎曲，离骚屈子经。","欲知当日意，须向此中听。"]},{"t":"妻兄任以道生朝","f":"七言律诗","c":["月律从渠大小旬，先生随意作生辰。","以谦自养何嫌晦，与复俱来特地新。","千岁日将宫线数，五方云作寿香陈。","葭灰寂寞今无赖，拟向黄钟托此身。"]},{"t":"承甫兄生日用去腊见惠之韵","f":"七言律诗","c":["留住东风一荚蓂，伴他南极老人星。","暂栖鸾凤官无小，晚插貂蝉梦自灵。","五十买臣多富贵，八千庄叟定年龄。","腰间六印都如斗，依旧双髦帖鬓青。"]},{"t":"林通判","f":"七言律诗","c":["东里相君新说似，茶陵军使美无穷。","谁知楚户南公口，更说沂康别驾功。","人借一凉鏖铄石，天开四荚照垂蓬。","不争玉女秋期日，自醉金公生数中。"]},{"t":"武学蔡博士挽诗 其一","f":"五言律诗","c":["人怜蔡庆远，庆远自悠哉。","虽欠寿将位，非无时与才。","诸生尊谊槩，明主识奇瑰。","独把平生去，何曾一语哀。"]},{"t":"武学蔡博士挽诗 其二","f":"五言律诗","c":["天子昔好武，儒臣皆讳文。","谁能有胜具，不肯建奇勋。","半世观行己，千年劝事君。","底须登大耋，金印负前闻。"]},{"t":"武陵道中元日自叹","f":"七言律诗","c":["流光冉冉道无闻，短发萧萧雪见侵。","衰矣久无天下志，行乎聊慰老人心。","功名随世吾何感，道德康时力未任。","安得万牛呼古柏，武夷山下白云深。"]},{"t":"治装将归","f":"五言律诗","c":["又作瞿唐去，长为道路行。","滩名暗可数，风浪饱曾更。","僮仆般移惯，衣装结束轻。","别多难得泪，不是总无情。"]},{"t":"法轮道中大雨","f":"五言律诗","c":["淋浪翻一雨，拳局下层坡。","险尽平川出，村宽古屋多。","风烟随地辟，鸡犬觉声和。","田父正愁思，天阴难刈禾。"]},{"t":"直州次韵丁教授送行二首 其二","f":"七言律诗","c":["送行第一要君诗，一路看诗慰所思。","可吏可儒仍可将，吾兄吾友亦吾师。","暂移马舫仿亭榭，小簇螺盘话别离。","指点方壶门外柳，归来须及欲黄时。"]},{"t":"直州次韵丁教授送行二首 其一","f":"七言律诗","c":["谁唤新霜破晓扉，江神知我向庭闱。","直州千古送人处，一棹横江从此归。","帘额北风情索索，轿窗东日薄晖晖。","树头鹊子能传喜，欲去回头更整衣。"]},{"t":"直舍窗前绿树","f":"五言律诗","c":["绿树几年栽，窗应为尔开。","阴中无暑到，缺处有风来。","长日宜佳寝，黄昏未忍回。","今年缘底事，归思忽难裁。"]},{"t":"直洲再赠江道士","f":"七言律诗","c":["玉台山里未能归，满世间人总可疑。","道士但行安稳处，先生应蔑刺讥词。","重来晓日芳洲上，却忆经年痛饮时。","未必蓬山陈少监，今朝閒暇得相思。"]},{"t":"绍兴孙察推席上","f":"七言律诗","c":["孙郎觅句有新声，场屋当年更老成。","曾草摩空殿前赋，却来晚饭越中行。","僧廊罢雪窗犹曙，佛塔无风铎自鸣。","客到莫嫌花酒少，三从事与两卿卿。"]},{"t":"绍兴次韵赵成卿闰七夕","f":"五言律诗","c":["乞得天孙网，人间巧已多。","还逢闰重七，奈此众儿何。","耕织关民事，婚姻自俗讹。","乾坤大务本，观象莫蹉跎。"]},{"t":"绍兴送妻弟任县尉归邵武二首 其二","f":"五言律诗","c":["场屋追兄弟，闺门托妇壬。","传家深属契，为客细论心。","何物尉乃勇，所居官不侵。","相期爱蜩甲，突兀看穹林。"]},{"t":"绍兴送妻弟任县尉归邵武二首 其一","f":"五言律诗","c":["珍重任公子，君行定几时。","重来未有日，此别可无诗。","带雨登闽峤，因□想蜀碑。","两翁门户在，努力慰相思。"]},{"t":"绍兴送彭世昌归应乡举","f":"五言律诗","c":["客有功名志，时平未急才。","泪临淮水落，眼向越山开。","且著莱衣去，仍随桂子来。","春明见天子，可以议云台。"]},{"t":"试学士院闻大驾过重华宫","f":"七言律诗","c":["君王凤辇过龙楼，清晓都门积雨收。","泪落三朝馀父老，春生簇仗万貔貅。","群公就日丹衷罄，索虏闻风逆胆羞。","湖海小臣心未已，更陈千虑向鳌头。"]},{"t":"郑子仁生日用其去臈见寿韵 其二","f":"七言律诗","c":["月日巧当真四六，风流合是妙词章。","金华洞府神仙骨，丽泽书堂翰墨香。","陇麦秋时椿自好，林莺老去鹤偏长。","绿槐宫阙薰风里，看引诸儒对殿廊。"]}]};